/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240924-5","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を99件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"目的としては、今説明があったと思うのですけれども、これがどのように調査されているのか、そして、この状況調査をもって直ちに悪質クレーム・カスハラとするものではないということでしたけれども、これを精査して認定された場合、どういう対応がされるのか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"この調査でカスタマーハラスメントが認定された場合ですけれども、内容精査も含めた上で、今後どのような政策を検討するかというようなことですので、認定するかどうかも含めて精査をしていきたいと考えています。","voiceIndex":15,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"昨年の８月に各課から状況調査ということで、これは今後もずっと続けていくものになるのでしょうか。それで、調査をどのように、各課から上げてくださいねということを、コンプライアンス推進担当のほうから、こうしろと促しているという形になるのでしょうか。各課の件数が分かれば伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"本調査を今後続けるかどうかについてのご質問ですが、本調査そのものは、まず、どういった政策を立てるかということもそうなのですけれども、今後、他自治体などでも、例えば、職員個人に対していろいろアンケートを実施したりですとか。","voiceIndex":17,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。これは、悪質クレーム、そしてカスハラの状況調査をして、今後、生かすというのは、どういう形になるのでしょうか。具体的なところで、この請願・陳情の中に対応業務が増大しているというところでは、実際にどの程度増大されているのか、分かれば伺いたいのと、職員が安心して働くことが妨げられている状況というのは、具体的にどういう状況か、分かれば伺いたいのですが。","respondent":"石井コンプライアンス推進担当課長","answer":"そういったときに、職員個人が抱え込むのではなくて、それは上席である係長、課長ですとか、そういったところも含めた上で、組織的にきちんと内容を検討しながら対応していくこと、それが大切だと考えております。","voiceIndex":19,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"言論封殺にもつながっていくと私も思います。なので、これが認定されるものではないということですけれども、このこと自体が悪質クレームとカスハラの状況調査として上がっていること自体、少し問題なのではないかなと思うのですけれども、そこはいかがでしょうか。","respondent":"石井コンプライアンス推進担当課長","answer":"先ほども申し上げたとおり、これをカスタマーハラスメントというような形で認定するようなものではございませんので、この調査票に載っていることそのものについては、どういう認識でいるのか、そういったことも含めて調査票の内容を今後精査していくものであると。","voiceIndex":21,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"請願権ですから、陳情にも書かれていますけれども、憲法にも定められた権利を、区が悪質クレーム・カスハラの状況調査として挙げているということ自体が私は問題だと思いますし、そもそもなぜこれだけの請願・陳情を上げなければいけないか、そういう区民が追い込まれている状況にこそ寄り添うべきだと思いますし、これを悪質だと、カスハラだと言うこと自体の感覚が問題だなと感じていますので。","respondent":"中道都市開発課長","answer":"そうした中で……。","voiceIndex":23,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、第４０号のほうの区長との面談のところです。そこについて少し伺いたいのですけれども、住民要望を受けた２人の議員の名前も出ていますけれども、この２人の議員から、何を依頼されて、その後、具体的にどのように対応して、区長からの返事はどのような内容だったのか伺いたいと思います。それで、区長室長から返答されたということですので、室長から、もし伺えればと思います。お願いします。","respondent":"石井コンプライアンス推進担当課長","answer":"内容につきましては、こちらの陳情に書かれてありますけれども、７月２９日に区長室に足を運び、区長室長を通じ面会を求めましたけれども、今回、民民の内容というふうなことですので、面会をお断りしたです。","voiceIndex":27,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"面談を依頼されるに当たっても、どういう内容の依頼をされて、そして、その後、区長からどういった返事で室長から議員のほうに会いませんよという返答が来たのか。その具体的な経過を伺いたいのです。どういう依頼をされて、区長からはどのような返事が来たか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"こちらは陳情書にも書いてありますけれども、区長室長を通じ面会を求めたというようなところで、８月１日に区長室長から電話で、再開発事業は民民の問題なので、地権者との面談には応じられませんというようなことで回答を差し上げているものです。","voiceIndex":29,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたら、区長室長からの返答が区長からの返答だったということで確認させていただいていいでしょうか。そこを確認させていただきたい。全ての区民と区長が会うということは難しいと思うのですけれども、区長が区民と面談するしないを決める基準は何かあるのか伺いたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"面会をする、しないの基準、例えば、内規として何か面会基準を定めているとか、そういったことではございませんけれども、区長は総合的に区政を推進する立場において、必要に応じて面会をするしないを適切に判断しています。","voiceIndex":31,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"以前は、前区長は、再開発を推進する側の皆さんとは面談されているのです。それは区のホームページにも出されております。森澤区長は、こうした再開発を進める推進側の皆さん、また、反対する側の皆さん、どちらとも会わないものなのか、どういう基準なのかということがもう少し分かるといいなと思うのですけれども、いかがでしょうか。","respondent":"石井コンプライアンス推進担当課長","answer":"区長室長から面会の申込みのお断りをさせていただいた際に、再開発事業は民民の問題なので、地権者との面談には応じられません、そのように回答しております。これが１つの考え方を表すものではないかというふうに考えられます。","voiceIndex":33,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、民民ということであれば、開発を推進する側の人たちとも今後は会うことはないと、そういうことだということが確認できたと思うのですけれども、でも、私は、この民民の話ということが、再開発についてだと、公共事業だと品川区は言いますよね。区が密接に関わっている事業なので、民民だから介入しないというのは通用しないと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"市街地再開発事業ですけれども、冒頭でご説明した繰り返しになりますけれども、市街地再開発事業の組合が設立するというところは、権利者の同意のもと、こちらは都市再開発法のところにありますけれども。話し合いが行われて進んでいくものになります。","voiceIndex":35,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当にいつもこうやって準備組合と住民の皆さんで、住民発意で再開発が進んでいるという説明をされるのですけれども、公共事業とおっしゃっているではないですか。都市計画決定がされれば、それはまさしく公共事業になるわけですよね。民民という形では片づけられない問題だということで、区議会議員も２名入って面談を申し入れたのですけれども、そこはどうお考えでしょうか。伺います。","respondent":"石井コンプライアンス推進担当課長","answer":"区長が直接会うかどうかについては、区長室長からお答え申し上げたとおり、再開発事業は民民の問題なので、地権者との面談には応じられないということでお答えをしています。","voiceIndex":40,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そういう立場にある区長ですから、タウンミーティングでない場でも、区議会議員が仲介に入ったわけですから、そこで区民から責め立てられたりとか、そういう場ではないわけですから、そういう場には、私は民民というふうにすること自体に無理があると思いますし、そういう声にぜひ応える立場に立っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"カスタマーハラスメントの調査ですが、改めて、目的と、その調査について公開するということを想定していたのか伺います。今回、こういうふうに具体的な文言が出ているわけですけれども、これが出てくるに至った経緯についてお願いします。","respondent":"石井コンプライアンス推進担当課長","answer":"本調査の目的ですけれども、昨年の８月に実施した際には、区に対する悪質なクレームが業務に支障を来す事態まで発展しているケースが増加しているというようなところで実施したものです。","voiceIndex":44,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"今、「認識」というお言葉がありました。なので、本件をカスタマーハラスメントと、３９件ほど上がってきているかと思いますけれども、これを認定しているか、していないかで言ったら、認定はしていないということも先ほどご答弁があったと思います。改めて、今度は、都市開発課長にお伺いしたいのですけれども、これは、こうした声が職員の声として上がったということでよろしいですか。","respondent":"中道都市開発課長","answer":"職員のほうから声が上がったものになります。","voiceIndex":46,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"これ、共産党、先ほど、この内容についてるるご質疑されていましたけれども、本当にそれでいいのかなと思います。その中で、これをもしハラスメントとして認定したら、それはいろいろ議論はあると思うのですけれども、職員から上がってきた声に対して、るる、それはおかしいのではないかというような内容をおっしゃっていましたけれども、これ、例えば、現職の議員が職員の方にいろいろと要望をしていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"いろいろ議論させていただいて、よく分からないのです。これは内部資料だけれども、情報公開請求すれば出てくるという認識でよろしいですか。だから、今回も、そういう請求があったので外に出てきたということでよろしいのでしょうか。その標題として「悪質クレーム・カスハラの状況調査」という資料になっているのでしょうか。そこを教えてください。","respondent":"石井コンプライアンス推進担当課長","answer":"調査の標題ですけれども、各所管に依頼をしたときの事務連絡の内容としては、「悪質クレーム・カスタマーハラスメントの状況調査について」ということで依頼をしていますので、それが調査の名称です。","voiceIndex":50,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"だから、こういうことになるのではないですか。だから、アンケート調査をとるときに、「職員の方々、困っていることはないですか」とか、違う表現だったら、これは公文書でいくわけではないですか。どこからがカスハラなのか、どこからが悪質クレームなのかという、「クレーム」ではないです、「悪質」ですからね、そこの判断は、誰がどういうふうにして、こういう標題をつけたのですか。","respondent":"石井コンプライアンス推進担当課長","answer":"それは３つございまして、例えば、長時間対応を要するなど業務の遂行に支障があるということ、続いて、常習的であるということ、３番の悪質な相手であるということ、ということを調査の内容としてつけているものです。","voiceIndex":52,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"飛ばないようにしてほしいと思うのです。なのに、このままやってしまうと、ここは反省してほしいのです。違う方向にいくのです。そう思いますので、そこは反省してほしいのです。なので、そういうことと分けてきちんと考えていかないといけないのではないでしょうかという、非常に私はそこを疑問に思います。間違った方向に解釈されるような公文書であってはいけないと私は強く思いますが、いかがですか。","respondent":"石井コンプライアンス推進担当課長","answer":"今まさに東京都も、ガイドライン作成の過程において様々な議論をしながら指針を定めていっているところですので、そういったことも含めながら、きちんと進めてまいりたいと考えております。","voiceIndex":56,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、その曖昧さをどう解決していくのか。でも、問題を解決するには、職場改善ではないですか。やり方はどうですか、いいのですか、今の状況でということも、やはり今までの流れでずっとやってきたから、準備組合ができて、そういうことがあって、権利変換とかいろいろあってという流れでやっていくのは、法律的な流れは分かります。これの意味が分からないので、そういう実例はあったのでしょうか。","respondent":"中道都市開発課長","answer":"準備組合が、今、合意形成というところで、権利者の方に個別面談等を行っているという状況ですが、準備組合に確認したところ、こういった状況はとっていなくて、個人面談を行う際には、事前に時間調整等を行って、相手に配慮した形で対応しているというふうに聞いております。","voiceIndex":58,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"これを本当にやっているとすれば、相手がそう感じているということも、やっているというふうに、相手の認識がそうであれば、そういう感覚になってしまうのです。ただ、こういうふうに書いている以上は気になります。本当にきちんとやってくれているのですかと。やはり相手側がいることでありますので、それをきっちりと尊重しながら丁寧に対応していただきたいということを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、もう１回、確認をさせていただきたいと思います。昨年からですか、新聞、テレビ、報道で様々出てまいりましたが、企業の社員や、自治体の職員を業務上で精神的に悪質な発言から身を守るために、カスタマーハラスメントというものが脚光を浴びたと思います。１人の社員でもやはり辞めさせたくない、何とかこのまま区民のために働いていただきたい。誰しも思う普通の成り行きだと思うのです。","respondent":"石井コンプライアンス推進担当課長","answer":"やはりこういった中で、区の職員の働きやすい環境を守るため、そして、もちろん、今後、東京都の議論等もありますけれども、そういった悪質なものに関しては組織としてきちんと対応していくため、今後、職員が相談しやすい環境をつくるため。","voiceIndex":62,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今再度確認させていただいたのですけれども、私は、この方針は決して間違っているとは思わないし、区としては、やはり最善というか、よりベターな方法で、今、少しずつ一歩一歩進んでいると思うのです。ですけれども、どうか一人一人の職員を大切にして、長く勤めていただけるように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"確認","question":"もういろいろ質疑を聞いていたので、１個だけ確認したいのですけれども、この状況調査が、職員の相談環境をつくりやすいものにというのは分かりました。そうすると、職員が素直に書いた言葉を、活字は難しいではないですか、見方によってはどうとでもとられてしまうので、そこら辺は、すごく私は不思議で、そうすると、職員も自分の文字として残すことができなくなってしまう。","respondent":"石井コンプライアンス推進担当課長","answer":"委員がおっしゃるとおり、個別具体の回答内容については、同じような内容を１つにまとめながら、こういう内容の回答が多かったとか、こういったところに、現在、職員が困っているようだというようなことで精査をすることができます。","voiceIndex":66,"id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。その中で、今回、このように議会に陳情が出されました。それで、今回情報公開請求をされた中で、今回は、この再開発についての部分の陳情ということで上がってきていますけれども、情報公開をされたときは、３９件のうちのどこかの一部分が公開されたのか、全体が公開されたのか、そこら辺を確認させていただきたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"個々の区民が行った情報公開請求の詳細そのものについて申し上げることは難しいですけれども、今回、情報公開請求、例えば、この悪質クレーム・カスタマーハラスメント調査というふうな調査で、例えば調査票の開示を求めるという情報公開請求があった場合については。","voiceIndex":69,"id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"公開されるものが、課から上がってきたものをまとめて、それに対する回答というようなイメージでしょうか。それが何かしらの検討がされてまとめられたものが課に戻って、それが公開をされているということですか。","respondent":"石井コンプライアンス推進担当課長","answer":"昨年度９月に各課にフィードバックした内容ですけれども、その中でどう対応するとかというような検討がされたものではなく、まず、各課からこういうような声が上がりましたということで一覧にさせていただいたものです。","voiceIndex":71,"id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問","question":"そうすると、今もそれぞれの質疑の中でありましたが、今回のこの調査は、ハラスメントと認定をするものではなくて、今後に生かしていくというところで、今、渦中であるということが質疑の中で分かってきているのですが、今、一旦はフィードバックしたものが課にありますということも踏まえて、今後、区としての対応の仕方について、最後、お聞きしたいと思います。","respondent":"石井コンプライアンス推進担当課長","answer":"東京都に関しては、ベーシックな部分での定義規定ですとか、各事業者がそれぞれの事業者の実態に合わせて対応要領をつくるといったような形で指針を示していますので、今後、区としても、では、今度、区の実態に合わせて、どのように職員が対応したらいいかとか。","voiceIndex":73,"id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"まさしく今、東京都が議論中であります。どういう内容が出てくるのかということがまだ見えていませんけれども、都がやっていることをそのまま横引きするのではなくて、そこは品川ナイズしたものにしっかりとしていただきたいということを要望させていただいて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういう意味では、そもそもカスタマーハラスメント調査票からの削除を求めるということで認定もしていないということでありましたし、陳情第４０号についても、そもそもこの調査自体が特定の方たちを悪質クレーム・カスタマーハラスメントということを認めるような調査ではないということが先ほどのご説明でもあったので、不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、私は削除すべきだと思いますし、もう１つの民民だから会わないという区長面談のところ、そこも民民だからという理由で、区長が今回の件で会わないということは、住民は納得がいかないと思いますし、私もそう思います。再開発の問題点は、私たちも、この間、様々指摘はしてきましたけれども、今回の計画で苦しんでいる住民の声を直に区長自身が聞くべきではないかと思っていますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"本日結論を出す、不採択です。少し補足、繰り返す部分もありますけれども、これ、きちんと言っておかないと大きな問題だと思うので申し上げます。「何か困り事ありませんか」というふうなアンケートでいいのではないかという話もありましたけれども、これ、セクハラとかパワハラのときも同じことを言えるのですかという話なのです。これはセクハラも一緒ではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。これ、議論がありましたけれども、今後、公文書の在り方を考えてほしいです。文章は本当に怖いのです。だから、これも再開発の問題、根底からの問題を考えないといけないときに来ているのではないですかという提起なのですよね。だから、いい方法はないのかということを、やはり今後考えてほしいなと、まちづくりは特に考えてほしいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-031"},{"speaker":"まつざわ委員","kind":"意見","question":"結論を出すで、不採択です。認定するものではないという、今後の検討をどう生かしていくかということがこれからの議論の方向性だと思いますので、先ほどおっしゃっていましたが、区がオリジナル、品川区独自の方向性をしっかりと決めていただければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-032"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。すみません、さっき２つまとめてだと思って言ったのですが、理由としては基本的に同じで、実態調査をしているというところで、そもそも認定していないというようなことから、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"意見","question":"本日結論を出すで、採択です。先ほどと同じですけれども、やはり憲法に認められた請願権を理由にしているというところでは、悪質クレーム・カスハラには当たらないと思いますということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-034"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"八潮の特別養護老人ホームの増築ということで、学校跡地が特養ホームになったのが八潮南特養なのですけれども、その校庭部分等を使って増築するということだと思うのですけれども、増築部分で何人分でしたか確認させていただきたいのと、私たち、この間、特養ホームが足りないからつくってということを様々要望してきたのですけれども、そのときに、１００人分を建てるのに、およそ２０億円と区からも聞いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"ＺＥＢ化、答えられるところでいいのですけれども、課が違うかもしれないですけれども、ＺＥＢとかＺＥＢ Ready、Nearly ＺＥＢ、ＺＥＢ Orientedでしたか、様々ＺＥＢも種類があるのですけれども、どのＺＥＢにするのかということを決めるのは、規模とか、施設の用途とか、そういうもので決まりというか、基準があるのか、どうやって決めているのか伺えたらと思います。","respondent":"長尾施設整備課長","answer":"ＺＥＢの認証のレベル感ですけれども、実際に設計を進めていく中で、ＺＥＢ Readyまでなのか、Nearly ＺＥＢまでいけるのか、そういったところが決まってきますので、設計の当初の段階では、ＺＥＢ認証を取得できるように検討を進めるというところで、現在は。","voiceIndex":105,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"これ、不思議だなと思うのは、共同体をつくるときに規定はあるのですか。なぜこの２つの企業が共同企業体という形になっているのかと不思議なのです。これは金額が低いからということなのでしょうけれども、品川区の企業共同体として入札をかけているということなのですか。どういう決まりがあって、こういう形態になっているのかなといつも不思議なのですけれども、いかがでしょうか。","respondent":"佐藤経理課長","answer":"ただ、なかなか今回のように大規模なところでは、そういった条件を出すと、応札していただける事業者が見込めないということであると、そこを外した上で自由にというか、応札していただいて、結果的に、他自治体の事業者が１番をとっているという状況かと思います。","voiceIndex":108,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"港区、千代田区、中央区ですから、それなりの大きな企業があるということは分かるのですけれども、ただ、この共同企業体をつくるときに、いろいろな見方があると思うのです。その辺はどうなのでしょうか。もしかしたら、ほかの、例えば港区、目黒区、大田区みたいな、そういう企業体でもいいと言えばいいですよねというふうに思うのですけれども、その考え方はいかがですか。","respondent":"佐藤経理課長","answer":"ただ、２番あるいは３番のところは区内の事業者を入れてくださいというような形の条件を出して募集しているというところがありますので、そういった区の原則として区内事業者に受注機会を確保するというところに基づいてやっているとご理解いただければと思います。","voiceIndex":110,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"その気持ちは分かるし、応援をしていきたいという気持ちもあるのですが、これは産業振興のほうに入ってしまうので、あまり言いませんけれども、やはり区内事業者が１番をとれるぐらい、そういう推進というか、それも必要だろうと思うし、これだけ見ると、何か取ってつけたように、港区が大きい大手企業が入って、品川区の業者からと、取ってつけたように品川区の業者を２社入れる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"ただ、作業着だけは淺沼組の作業着を着ているというようなことを少し聞くのですが、こういうことは、実態調査、チェックはしているのでしょうか。それから２番目に、入札金額の積算ですが、これ、どう見ても、ほぼ１００％に近いのではないですか。それとも、積算する会社に依頼して、このような金額を出しているのですか、これについて教えてください。","respondent":"長尾施設整備課長、佐藤経理課長","answer":"３つ目の積算に関しましては、入札に当たって、予定価格につながるような積算については、施設整備課のほうで積算分を行って出しているという状況です。一定額以上、１,０００万円以上の契約案件については、事前に予定価格を公表した上で応札いただいているという状況ですので、１つは、その金額を一定の基準としまして。","voiceIndex":113,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"それに、課長、お優しいので、ただ、自分の家などを直すなり、改造、改修するなどと言ったら、やはり１円単位までチェックすると思うのです。それと、先ほど、共同企業体でそれぞれ仕事をやって割り振りをされているということですが、私が先ほど申し上げたのは、実態調査をしているのですかという話です。書面で、今日はＡ社がこの工事をやります。そういうことは考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-042"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、今回、辞退が増えて、落札が１者になっている契約が２件あるというところで、区としては、どのように捉えているのかを教えてください。辞退理由も、配置者が困難なためがほとんどで、積算金額が予定価格を超過したというのは１件だけだったのですが、それも踏まえて、どういうふうに捉えているのかということを教えてほしいと思います。","respondent":"佐藤経理課長","answer":"他自治体のところでは、委員ご指摘のとおり、落札不調、応札するところがないという状況もあるということは把握しておりますので、事前に、年間でこういう工事を予定しています。","voiceIndex":118,"id":"exchange-043"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。理由としては、そういうことが挙げられるということで、今後、そうした需要が一定落ち着けば、またいろいろな入札が増えてきて、１者入札ということが減るのかなとも思いました。年間工事についても、なるべく早く反映しながら、応札が増えるようにということで工夫もされているということで分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-044"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"これがどの段階で区のほうに申入れがされてきているのか、これは入札をして金額を出して、その後の段階なのか、教えていただきたいと思います。","respondent":"佐藤経理課長","answer":"その後に詳しい設計図書を見ていただいて、どのぐらいの手配をするかということを、それぞれの企業が算定して応札していくということですけれども、このタイミングで技術者がこちらには配置できないと判断されたところについては。","voiceIndex":122,"id":"exchange-045"}]},{"id":"topic-02","title":"第８５号議案、プレハブ冷凍冷蔵庫他の買入れ","agenda":"第８５号議案、プレハブ冷凍冷蔵庫他の買入れ","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"それと、１５ページの５番で、主な買入品目ということで、様々挙がっておりまして、それでも他というものが、またこれ以外にもあるのだろうなと思うのですけれども、これまで荏原特養の厨房になかった新しい厨房機器は、この中にはない、今まで使っていたものを同じように買い入れるということでいいのか、その確認だけ。","respondent":"菅野高齢者福祉課長","answer":"それ以外の今のものに比べて、備品・機器が新しいものかというところは、基本的には、今あるものと同じようなものをベースに、事業者とも打合せをさせていただいておりまして、ただ、もう２５年たっておりますので、機械も新しくなっているというところで、その辺りは。","voiceIndex":155,"id":"exchange-046"}]},{"id":"topic-03","title":"第７６号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","agenda":"第７６号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"今のご説明だと、文言整理がされるだけで、区民への影響は変わらないということで確認させていただいていいでしょうか。","respondent":"横田デジタル推進課長","answer":"委員ご指摘のとおり、区民への影響はないものであります。文言修正になります。","voiceIndex":179,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"ちょっと教えてほしいのですが、今、区民には影響はないというご答弁なのですけれども、これ、改正の理由の中に、区独自の個人番号の利用および情報提供ができるとなっているのです。","respondent":"横田デジタル推進課長","answer":"それが、この度、法令に基づく内容に変わりましたので、条例改正するものです。３番目の生活保護法に関する規定整備ですが、こちらも法律の「進学準備給付金」の名称が「進学・就職準備給付金」というふうに変更されたことになりますので、こちらで変更になります。","voiceIndex":182,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"これをさらに広げていくと、品川区としては、どのような広がりを持って、要は、個人情報ですから、いろいろ使われる要素が広がってくるのか、それとも、そこまでは考えないで、国の法律が変わっていったときの文言整理だけですよということなのか、そこの、これからの進め方、適用の仕方も含めて教えてください。","respondent":"横田デジタル推進課長","answer":"ご指摘のとおり、法律の変更に伴う文言修正になりますので、特に区民への影響はないものです。事務の運用に関しましても、(2)の私立幼稚園につきましても、これまでもやってきたものですので、特に運用の変更はないものであります。","voiceIndex":184,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"最後に１点。分かりました。では、全く影響がない、今までやってきたことだしということで、文言整理をしましたということだと理解しました。この仕事は、デジタル推進課の仕事になるのですか。なぜデジタル推進課なのだろうなと、少し不思議だったのですけれども、ほかのところではないのか。マイナンバーカード関連だと、デジタル推進課になるのでしょうか。担当の在り方を教えてください。","respondent":"横田デジタル推進課長","answer":"こちらのマイナンバーの条例に関することですとか、マイナンバー制度の運用全般ですとか、マイナンバーカードの利活用につきましては、全庁に関わることですので、企画経営部のデジタル推進課で行うこととしております。","voiceIndex":186,"id":"exchange-050"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。施行が令和７年７月１日となっておりまして、少し先の日付かなと思うのですが、今回、この段階でこれを出されているというのは、何か理由があるのか教えていただきたいと思います。","respondent":"横田デジタル推進課長","answer":"「進学準備給付金」の名称を「進学・就学準備給付金」と変更する規定整備が併せてございましたので、同じような生活福祉法関連ということもありますので、「生活困窮外国人保護事務」に関しても、併せて今回のタイミングで行うことといたしました。","voiceIndex":189,"id":"exchange-051"},{"speaker":"新妻副委員長","kind":"質問","question":"進学に関わる、来年の４月に関わるということがあって、併せて今回のタイミングという理解でよろしいでしょうか。","respondent":"横田デジタル推進課長","answer":"進学・就職準備給付金につきましては、もう既に施行されているものでございまして、もうすぐに条例改正する必要があったのですが、同じ生活福祉法関連でありましたので、令和７年７月１日で施行されるということが分かっておりましたので、生活困窮外国人保護事務も併せて、今回。","voiceIndex":191,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"関連なのですが、ということは、今までやってきたことなので、施行期日が来年の７月１日であったとしても、やることは、ほかの条例の中でやっているので問題ありませんと、区切りとして、この令和７年７月１日にしましたということでよろしいですか。","respondent":"横田デジタル推進課長","answer":"令和７年７月１日に生活困窮外国人保護事務の施行期日が法律によって規定されるということになりますので、条例は、それ以降、削られるというところで、このような記載としております。","voiceIndex":193,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成なのですけれども、マイナンバーについては、さらなる拡大推進というのは、私たちは、大本では反対をしておりますが、今回は文言整理、あと、生活保護のところでは、当事者の要望に応えたものにもなっているという国会での議論もありましたので、この件については賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区の説明があった１番の小規模住宅用地に対する軽減措置は、請願文にもありますけれども、昭和６３年度に創設されている。軽減措置を求め始めたときが、１番を見ると昭和６３年から、そこから、要は、軽減措置がなくなるから、こういう請願が出されるようになったのかとか、そういう経過が分かれば教えていただきたいのですが、いかがでしょうか。","respondent":"吉野税務課長","answer":"軽減措置の目的としまして、過度な負担の緩和、それから、小規模の非住宅用地の役割に加えて、中小企業の支援ということも目的としておりますので、昨今の厳しい経済状況を全て勘案して、こういったところの見直しをしていると認識しております。","voiceIndex":209,"id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、毎回毎回こうした請願が出されるという状況ではなくするために、区としても、国や都に、こういう経済状況ですから、継続は、少なくとも１０年間ぐらいはすべきだみたいな、そういうことを言っていくということは、してこなかったのか、しないのか、お答えいただきたいと思います。","respondent":"吉野税務課長","answer":"これに関しましては、これまでも実際には東京都が賦課徴収しておりますので、東京都の分野になります。ですので、これにつきましては、東京都の動向を注視していきたいと考えております。","voiceIndex":211,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"東京都なのですけれども、こういう苦しい状況に置かれているのは区民なので、その声を区として、要は、継続を、１０年間、こういう請願・陳情を毎年出さなくてもいいように、しかも、今後は、物価高もすぐに解消される見込みがないと言われていますし、そういう状況なので、区から求めていくということをぜひしていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"なので、まず、この意見書の効果、例えば、意見書ですから、出して終わりだと思うのですけれども、こういう結果が得られたという成果、それはどういうふうにはかられていますでしょうか。これは意見書だから、議会で意見書を出すということなので、理事者側として、何か効果があると実感しているのか、全然ないのか、この辺はどういう評価をされていますでしょうか。毎年同じことをされています。","respondent":"吉野税務課長","answer":"毎年こういった意見書という形で要望を上げていただいていますので、それなりの効果はあるので、こういった軽減措置が続いているというように考えております。","voiceIndex":215,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"もう何年やっているんですかという話ですよ。だったら、東京都に、これも当たり前でやってくれということを区からは言えないのですか。どうなのでしょうか。毎回毎回意見書を出して、議会から意見書を出した、はい、終わりということにはならないのではないかと、これだけ長く出しているわけですから、区としての動きは何かしらあっていいのではないかと思うのですが、いかがですか。","respondent":"吉野税務課長","answer":"こういった軽減措置が必要になってくるかと思います。私どもの税務課長会というものがあるのですけれども、そちらのほうでは、こういった課題が実は出ておりませんので、少し検討させていただきたいと考えています。","voiceIndex":217,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、全体の動きにしていかないと、東京都は動かないと思うのです。なので、都区財調の話もありますけれども、もう当たり前の、これ、こういう措置は当然だと、それを計算に入れてのベースになるような形をぜひ品川区としてもやっていただきたいのです。だったら、少しでも全体で底上げできるような状況を品川区発信でやってもいいのではないかと思いますけれども、いかがですか。","respondent":"吉野税務課長","answer":"実際にこういった状況を分析しまして、言える場所があれば、そのように確かめていきたいとは思います。","voiceIndex":219,"id":"exchange-060"},{"speaker":"西本委員","kind":"意見","question":"まとめます。行政側と、それから議会側とで、やはり底上げしていこうという、そういう雰囲気というか、もうそろそろつくり上げる。本当にこれだけでいいのかという話もあるのです。もっと先を見通して、そういう経済状況を鑑みたときに、もっと品川区内の事業者の方々が助かるようなことがあるのかどうかということがあってもいいのかなと思います。これは意見でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":221,"id":"exchange-061"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らく区長会でも、恒久化するように進言していると思うのですが、次の２つを入れていただきたいと思うのですけれども、都の歳入である固定資産税は、年々増えているのですよね。区がそういうことをやっているなら、区に入る、私は入らなければいけないと思う。確認ですけれども、今日、区長はいらっしゃらないですけれども、区長会で、毎年きちんと話し合っているのですよね。どうでしょうか。","respondent":"堀越副区長","answer":"今回の場合は、そういった中での税の負担に関する提言についての、この請願についての総務委員会の審議だと認識しておりますので、税の負担を軽減するという観点と、それから、区として、本来は、本来はという言い方が正しいかどうかはあれなのですけれども、固定資産税などは。","voiceIndex":222,"id":"exchange-062"},{"speaker":"須貝委員","kind":"質問・要望","question":"企画のほうで企画経営部長も、やはりもっと発言して、私は、闘うべきところはしっかり闘っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-063"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"公明党も、結論を出す、採択で、紹介議員にもなっておりますことから、意見書も出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出す、採択で、意見書も出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-065"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、採択で、意見書を出すで、１個だけ、これ、提出者というよりも、紹介議員になられている各会派の皆様になるのかもしれませんけれども、この請願の表現で「サラリーマン」という表現があります。ご案内のとおり、品川区は、ジェンダー平等の条例を出しているところなので、通常は今、多分、用語としては「会社員」という言葉を使うのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-066"}]},{"id":"topic-04","title":"令和６年陳情第４８号、事業者へのインボイス制度の影響について品川区内実態調査実施の陳情","agenda":"令和６年陳情第４８号、事業者へのインボイス制度の影響について品川区内実態調査実施の陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今回すごく具体的な陳情が出されたなと思っています。改めて区民の暮らしと生業、地域経済を振興すべき品川区として、インボイスが中小・零細企業、個人事業主に影響を与えていると認識はされているでしょうか。調査を行う必要があると思わないかどうか、まず伺いたいと思います。","respondent":"加島財政課長","answer":"一概に数字の面から影響ということは、区のほうで全体の実態把握は難しいところですけれども、今、数字の状況といたしましては、増加の傾向を示しています。","voiceIndex":241,"id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、調査を行う必要性がないと感じられているのでしょうか。それで、こういう企業、中小業者、そして個人事業主の実態ということなので、所管課の課長を、今日、呼んでいただいているというところでは、委員長に感謝申し上げたいと思いますけれども、そこであれば、今の質問に関してお答えいただけたらなと。お願いします。","respondent":"小林地域産業振興課長","answer":"本制度については、先ほど、財政課長が説明したとおり、国の制度です。その実態調査についても、制度そのもの、あるいは、個別の事実関係なども含めて、責任ある政策判断および施策実行の権限、専門的知見を有する国において判断すべきところです。","voiceIndex":243,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこはぜひやっていただきたいと思うのですけれども、いかがでしょうかということと、今回、この陳情を出された方からも、参考資料として、「インボイス制度におけるフリーランス等の７０００人実態調査報告」、７,０００人実態調査に寄せられた声、あと、品川区内の一部で集めた独自アンケートがなされておりますけれども、これらは、区の所管としては、確認されている。","respondent":"加島財政課長","answer":"１点目にご質問いただきました、区として実態調査を国に求めていくことができるのかどうかというところですけれども、先ほど冒頭にご説明申し上げたとおり、インボイスは国の制度ですので、国の責任において実態調査を行うどうかは主体的に判断すべきと考えております。","voiceIndex":245,"id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"確認","question":"この資料の存在を認識されていたか、中身も確認されているかということを伺ったのですけれども、あと、国も若干動いているということもあるのですけれども、とても急を要する、本当に今、苦しんでいる状況なので、区として把握する必要は、国が今、把握しようとしているという答弁でしたけれども、区として把握する必要はあると思っていないのでしょうか。伺いたいと思います。","respondent":"加島財政課長","answer":"陳情についてきた詳細な資料を確認されたかという点では、拝見させていただきました。区として実態調査を行う考えはないのかというところですけれども……。","voiceIndex":247,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"影響しないのですか。品川区の区内経済の土台だと思うのですけれども、このインボイス制度が与えている実態、国が把握することとおっしゃっているので、区としては把握していないのかどうかも伺いたいのですけれども、そして、今申し上げた、この会の皆さんが出された資料、それにも、声は、区内ではないにしても、全国の声が出ているわけです。改めて伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"引き続き、国や都の経済対策の動向ですとか、それぞれの対応能力に応じて、地域経済の下支え、あるいは消費喚起などにつながる施策をしっかり進めてまいりたいと考えております。","voiceIndex":251,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この陳情文にもあるのですけれども、前回、私も実態調査を求めましたけれども、該当する課で相談も受けているというふうに答弁がありました。だから、調査は行わないというふうに答弁されたのですけれども、では、区では、どれほど、何件、どのような内容で相談が寄せられているのか教えてください。","respondent":"小林地域産業振興課長","answer":"ただいまのご質問で「経営相談窓口」というところで、品川区でいきますと、年間３,０００件、４,０００件といった経営相談の対応がありますけれども、インボイスに関連したような直接的な相談は、我々、認識してございません。","voiceIndex":253,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったアピールをしていただきたいと思うのですけれども、いかがでしょうかということと、今おっしゃったコールセンターなどは、陳情にもありますけれども、実態調査をしないという理由にはならないというふうに書かれているのです。私も理由にならないと思うのですけれども、そこはいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"そういったところも含めて、制度の案内などもしっかりやっていくということと、ただ、実態調査というところにつきましては、やはりそういった関連情報なり、あるいは権限も含めて、専門的知見も含めて、そういったところの国の対応ということで。","voiceIndex":255,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり先ほどから言っているのですけれども、区内の企業の経営の問題なので、ぜひ国にも求めていただきたいですし、国は、なかなか進まないというところがあるので、こういう陳情で区で実態調査してくださいということが出ているわけですので、ぜひやっていただきたいと思うのです。やるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問","question":"この陳情、なぜ総務委員会にかかっているのでしょうか。おかしくないですか、これ。誰が決めたのですか。今回のこの陳情は、事業者へのインボイス制度の影響について、要は、地域産業、品川区の産業、経済産業を含め、どうなっているか調査をしてくださいですよ。なぜ総務委員会なのですか。話し合うところは区民委員会ではないですか。総務委員会で何の話をしろというのですか、これ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"おかしいですよね。それで、さっきの答弁、苦しい答弁をされていましたけれども、どういう割り振りでここで議論するのですか。この内容は、品川区内の事業者がどうなっているかということを調査してくれという陳情です。なぜ総務委員会でやるのですか、総務委員会でやる意味はあるのですか。それとも、国がやっていることだから関係ありませんと言いたいだけなのですか。どうなのでしょうか、お答えください。","respondent":"久保田企画経営部長","answer":"この委員会の付託は議会のほうで決めて付託されていますので、それに基づきまして、私どもとしましては、審査のときに質疑に応じているといった中で、総務委員会でできることということで、所管の課長にも来ていただいて、今、質疑の応答をしていますといった状況です。","voiceIndex":259,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"それならば、所管が違うのではないですかと言うことをできないのですか。でも、しっかり議論するのであれば、適切なところで議論するというのは、議長が決めたら誰も言えないということですか。だって、区民委員会だったら、それなりのいろいろな方がいらっしゃるのに、担当がいらっしゃるのに、そこで議論すべきではないですか。これは意見として言わせていただきたいと思います。お答えください。","respondent":"小林地域産業振興課長","answer":"そういった意味で、先ほど申し上げたような基本的な情報、登録情報、未登録情報というのは、これはこの品川区というか、自治体の中でのいずれの部署も所有しない情報というところがまず根本にありまして、そういった中で、ただ、中小企業支援というところでは。","voiceIndex":261,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"でも、国のいろいろな制度があって、それに対して困っている人がいる、その困っている人をどう引き上げていって助けられるかというのは、私たち地方自治体の役目ではないのですか。国がやるべきではなくて、品川区民の方々が、どういう現状があるのかというのは調べるべきではないですか。だったら、こういう中小企業関係で、今どうなっていますかということは調べていいのではないですか。","respondent":"小林地域産業振興課長","answer":"インボイス制度そのものについてというところで、制度自体の権限といいますか、個別の事実関係なども含め、責任ある政策判断および施策実行の権限ですとか専門的知見、そういったものを有する国において判断すべきものであると考えております。","voiceIndex":263,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"この内容。よく読んでいただきたいのです。それを問うているのではない。区民アンケートをいっぱいやっているではないですか、品川区。そうしたら、中小企業の実態調査、それから冊子、機関誌ですか、冊子を出していますよね。どういう影響が品川区民の皆様方に対してあるのかということを調べるのは、自治体として当たり前のことではなかろうかと思うのですけれども、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"インボイス制度につきまして、責任ある制度の政策判断も含めて、そういった調査の実態というところも、ある程度の情報というところで国が権限を持っているところですので、国において判断すべきものであると考えております。","voiceIndex":265,"id":"exchange-079"},{"speaker":"西本委員","kind":"提案","question":"区民アンケートは全区民に１億円ぐらいかけてやって、だけど、実際にどうなっているかという細かい調査をしないという、品川区にとっていい方向になる、やりやすいやり方とか、そういうものをばかりチョイスしているようにしか思えないのですけれども、やっているわけですから、品川区は。やったらいいのではないですか。だったら、その中から制度設計したらいいのではないですか。いかがですか。","respondent":"小林地域産業振興課長","answer":"品川区の実態ですけれども、インボイス制度が地域経済というか、自治体に与える影響というところも含めて、そういった基本的情報を持っている国が、やはり一元的に管理しているものです。そういった権限なり専門的知見という観点から、区で実態調査を行う考えはございません。","voiceIndex":267,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"これ以上言っても課長の心は決まっているかと思いますが、ただ、これだけは知ってほしい、ここだけは知ってほしいのです。いろいろな意味で調査をかけているではないですか。そこから次の世代の提言が出てくるのではないですか。施策が出てくるのではないでしょうか。やはり区民の人たちがどうあるのかということを常に意識していただきたいということを強く申し上げて、意見として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-081"},{"speaker":"まつざわ委員","kind":"確認","question":"何点か確認させてください。先ほどから、インボイス制度というのは国の財政措置、ここにも書いてありますが、税務署などが管理しているお話です。税務署でこのインボイス制度というものは全部管理しているということが、まず正しいのか。そこで管理しているということなのか、まず教えてください。","respondent":"加島財政課長","answer":"事業を新規に始めるときの登録ですとか、それから、何らかの理由で事業を廃止するとき、こちらの届けについては、所管の税務署に届出するということです。","voiceIndex":271,"id":"exchange-082"},{"speaker":"まつざわ委員","kind":"質問","question":"そういうものを税務署が管理しているのですよね。ということは、税務署が管理しているものを、例えば、先ほど、国と地方自治体というお話が出ていますけれども、例えば、国で管理しているものに関して、私たち地方自治体が、それに関する情報というのですか、事業者の情報というのですか、例えばインボイスもそうですけれども、そういった情報は、私たち地方自治体にしっかり共有されるものなのですか。","respondent":"小林地域産業振興課長","answer":"これは自治体のどの部局も共有していないものと認識しております。","voiceIndex":273,"id":"exchange-083"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、例えば、財政の状況、そういった管理情報が国から自治体におりていかない状況の中で、実態調査をするというお話が今回ありますけれども、そもそも、私も調査は簡単にアンケートをとればいいと思っているのですけれども、例えば、陳情の趣旨だと、インボイス制度の影響が出ている中で実態調査をお願いしますと言いますけれども、そもそも今の答弁を聞いていると。","respondent":"加島財政課長","answer":"そこが国の制度であるというところの難しいところでして、なので、私どもといたしましては、実態調査というよりは、実態調査は国の判断で実施すべきという考えは揺らぎませんが、ただ、地域産業振興課のほうで、中小企業ですとか、個人事業者への融資あっ旋、それから。","voiceIndex":275,"id":"exchange-084"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、年々物価が高騰しているということで、それぞれ事業を継続していくのに大変なご苦労をされている中に、インボイスがそこに入ってきたわけですから大変だなという実態は、本当にそのとおりです。質問しようかと思ったのですけれども、話を聞いていると、なかなか質問には至らないかなと思ったので、一応意見だけ言わせていただきたいと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":279,"id":"exchange-085"},{"speaker":"大倉委員","kind":"質問","question":"実際の実態調査をするというところの大変さは、今お話を伺っている中で非常に感じたところであります。","respondent":"小林地域産業振興課長","answer":"それ以外の部分ということでいきますと、やはり借入れを行った場合に、かえって返済が困ってしまうのではないかということが出てくるわけですが、そういったときの対応として、例えば、返済する必要がない補助金を使っていただくですとか。","voiceIndex":281,"id":"exchange-086"},{"speaker":"松本委員","kind":"質問","question":"国の事業だからという話が今日はたくさん出ていたので少し伺いたいのですけれども、国の事業、あるいは国の所管するもので、例えば制度が変わるということはよくある、それは消費税もそうですし、ほかの制度もあると思います。だけど、事業者は影響を受けている。でも、これは審査と関係するので伺いたいのですけれども、屋形船を入れたのは、当区の判断で入れたのでしょうか。","respondent":"小林地域産業振興課長","answer":"この屋形船の事業者を入れるという判断も、品川区のふだんの聞き取りも含めて、水産事業者、運輸事業者を両方やるべきだということで、対応したものです。","voiceIndex":285,"id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"品川区も現況調査と中小企業の景況調査はやられているかと思います。これは恐らくアンケートをとられてやられているのではないかと思いますけれども、これはアンケートの項目について、何か国から定めがあるのでしょうか。それとも、ある程度、区のほうで項目を追加することはできるのでしょうか。","respondent":"小林地域産業振興課長","answer":"ただいまご指摘の景況調査につきましては、これは東京都とか他区もやっているものでございまして、それに合わせて、そういうような内容ですとか、質問項目といいますか、景況感を聞くということを長期的に見て一番継続してやっているものですけれども。","voiceIndex":287,"id":"exchange-088"},{"speaker":"松本委員","kind":"質問","question":"お伺いした、区で独自の項目を追加することができるかできないかという点はいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"品川区として中小企業の景況調査をやっているものですので、質問項目とか、業種を一部改正ということはあり得るとは思いますけれども、実際、この事業者を把握するということも、我々もふだん事業者にいろいろご協力をお願いしながらですので。","voiceIndex":289,"id":"exchange-089"},{"speaker":"松本委員","kind":"質問・要望","question":"大体状況は分かりました。今の話をお伺いしていても、今回の調査を求められている方たちの願意に沿うというやり方が、国の制度だから絶対に不可能かと言ったら、そうではないし、恐らくやり方はあると思いますし、今、パッと調べただけでも、例えば、静岡市などは、実態調査というやり方ではありませんが、アンケートという形で調査を行うという手段もやっていらっしゃると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":291,"id":"exchange-090"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"区には、国の制度ではあるかもしれませんけれども、品川区民の方でありますので、事業主の方等でありますので、今後とも、そういう方のお声はしっかりと把握をしていっていただきたいということは要望させていただきたいと思います。この制度があることで、国においては３年間の支援措置等も進めてまいりましたが、それでも、現状、厳しいという実態があるわけであります。","respondent":"小林地域産業振興課長","answer":"例えば、個人の方が事業を進めるに当たっては、ＳＨＩＰですとか、西大井、あるいは武蔵小山といったところも、そういったフリーランスの方もたくさんいらっしゃると認識しております。","voiceIndex":295,"id":"exchange-091"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"品川区では、融資あっ旋の中において、物価高騰、エネルギー価格に対する事業支援は進めていて、新妻副委員長からもお話がありましたが、国に言うだけではなくて、そういった部分こそ、地方自治体からできることではないのかなと思っていますので、今以上にそういったご相談があった際は、積極的な支援といいますか、そういったものはどんどん拡充していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-092"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"本日結論を出すでお願いいたします。不採択でお願いします。この出された陳情に対して、様々、今回だけではなくて、皆様からお声をいただいております。そのことを区もしっかりと、今後も引き続き把握をしていただいて、具体的な支援策につなげていただきたいなという、そういう思いは要望とさせていただいて、今回の陳情には不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-093"},{"speaker":"大倉委員","kind":"質問・要望","question":"一方で、今、実際にお困りになられている中小・零細、フリーランスの皆さんの支援を考えなければいけないと思いますので、経過措置で負担割合が変わっていくという中で、そして今現在借りていただいている方や補助金を使っていただいている方などの声はしっかりと聞いていただきながら、今後の対応はぜひ進めていただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":300,"id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも、そのために国に区としては求めていくことをしない。以前、区民委員会だったときも、こうした借入れの返済を延ばしてほしいとか、そういう些細な願いでさえ否決されているのです。そういう状況でしたので、本当に姿勢を変えていただいて、地域産業を振興、守る、応援するというのだったら、そうした形をしっかりと、こういう請願・陳情に応えていただく形でもやっていただきたいと私はすごく思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど申し上げましたけれども、本来は、国のやるべき事業だと思いますが、これだけ物価高騰や人手不足などで小規模事業主や個人事業主が誠に厳しい経営状況にあるということを思えば、区から総務省や東京都などに働きかけ、事業主の実態を調査していただきたいと思います。今回の陳情に関しては、本日結論を出す、採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-096"},{"speaker":"松本委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。理由を述べします。これはきちんと言っておかないといけないと思います。それはなぜとったかと言ったら、国の制度ではあるけれども、居住されている当該自治体において影響を受けていらっしゃる方たちの声を聞いて、それで、例えば、国に何か要望を出していく、あるいは、自治体として何か対策をとることができないかということのためにとったアンケートだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"だけど、区民アンケートをとったではないですか。それをきちんと国交省に伝えているではないですか、区長自ら。副区長も行って、２回も行って。目の前に困っている人がいるのだったら、その実態調査をして、それに対する対応をする、これは議会でも、行政側でも、同じ気持ちであるべきだと私は思っておりますので、ぜひ見直しを図って調査をしていただきたいという強い思いを込めて、賛成としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-098"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"品川区民にアンケートを出しましたね。あの中で、最後に自由意見を書くスペースがあったと思うのです。それに、もうその前に、インボイスがいろいろ、様々、区民も多くの方が、そういう問題点について指摘しているかと思うのですけれども、そこには自由意見として、区に対しての意見として何か出ていたのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-099"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6823#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":68188,"voices":320}},{"id":"r06-20240925-6","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"区民委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度八潮地区まちづくり事業の進捗状況","agenda":"令和６年度八潮地区まちづくり事業の進捗状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"八潮みらい懇談会とコンセプト検討は、ともに支援のコンサルタントか何かが入っているのではないかと思うのですけれども、そちらは委託か何かだと思うのですが、業者名が分かれば教えていただきたいというのが１点と、八潮みらい懇談会について伺いたいのですが、改めて懇談会に参加しているメンバーの人数といいますか、構成みたいなのが分かれば教えてください。","respondent":"今井八潮まちづくり担当課長","answer":"コンセプト決定のスケジュールですけれども、まだ検討中のところはあるのですけれども、今年度末までにはコンセプトを決定したいというところで、年末頃に向けてある程度形にしていって、いろいろな方のご意見を伺いながら完成に向かっていきたいというところで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"コンセプト検討のほうを質問するのですけれども、別紙３のほうにアクティビティマップというのが、「重点的な施設およびその施設周辺で、どのようなアクティビティが行われているかを収集し、それをマップに落とし込んだ」という説明をされているのですけけれども、このアクティビティマップというのはどういうふうになったのか、ちょっと気になったので、どのような内容になったのかをお伺いしたい。","respondent":"今井八潮まちづくり担当課長","answer":"インタビューの対象年齢と職業ということで、八潮自治会連合会の会長ですとか、あとは防災協議会の会長ですとか、比較的ベテランとして今まで地域活動に取り組んでいただいた方からインタビューを開始している中で。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、カジノですけれども、自由に出してという場なので出るのは全然いいのですけれども、ただカジノというのは基本的に人の不幸の上に成り立つゆがんだ産業で、ギャンブル依存症も引き起しますし、まちの活性化だといっても正当化される施設では決してないと思いますので、私はコンセプトには入れるべきではないと思いますけれども、品川区の考えはどうなのでしょうか、伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"品川区のスタンスとしては、当然こういうセミナーの中でグループワークを実施して、各参加者に挙げていただいた意見ということで、貴重なご意見として扱わせてはいただくのですけれども、こういった出された意見を踏まえて。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは意見です。それともう一つ、５ページに「団地の空き部屋が宿に」という記載があるのですけれども、現状の八潮団地の空き室の割合、建物の種類によって違うと思うのですけれども、割合について伺いたいのと、あとその原因は何なのか、区として考えているところがあれば伺いたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"八潮団地内の課題といたしまして、やはり、それぞれの団地内の事業者が管理する土地については、基本的にはその所有者が責任を持って管理していただくということで、例えば植栽の部分についても。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"すみません、お店の課題についても何か書いてあったのですが、これについてはいかがでしょうか。課題の解決に向けて、区として今どのように考えているのか。","respondent":"今井八潮まちづくり担当課長","answer":"商業施設が少ないといったような課題は、これまでもずっと挙げられてきているところでございまして、こちらについても、なかなか行政主導で企業を誘致したりというところは、どこまでできるのかというところは難しいところではあるのですけれども。","voiceIndex":13,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"まちづくりコンセプトを検討していく中で、基本的なことですけれども、基本情報の整理で地区の概要、人口データの分析などと書いてあるのですけれども、ざっくりでいいので年齢層の人口データと、外国人比率なども併せて分かればお知らせいただきたいと思います。","respondent":"今井八潮まちづくり担当課長","answer":"外国人については、ちょっと手持ちの数字が古くなってしまうのですが、令和５年１０月１日時点の数字になってしまいますが、８７１人ということで、全体の数値からすると、７から８％程度です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"これが、３８９名の署名を添えて出されていたということで、担当の方にお聞きすると、やっぱり八潮地域に入浴施設がない、銭湯もない、お風呂でのコミュニケーションみたいなのが取れないというお話はよく挙がっていますという話を聞いていまして、署名がいっぱい、何でしょう、３８９筆つけて出てきた陳情とかを目にしていたので、何かこちらのインタビューのよく出る頻出ワードに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"別紙３にノルウェーとかニュージーランドの例が参考で出されていましたが、こういった取組は検討中ということであったと思いますが、紹介された事例などを実際に具体化するにあたっての現場の声とか、改めて課題とかについて教えていただければと思います。","respondent":"今井八潮まちづくり担当課長","answer":"その次の方についても、ちょっと違った特技を持っていたりとか、あとは八潮の地域内でやりたいことを持っていらっしゃる方というのを紹介していただくという形で、どんどん人材の数珠つなぎみたいなところも進めていきつつ、こういった具体的な活動に向けて。","voiceIndex":21,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"確認","question":"人材同士の結びつきということで確認させていただきました。次の地域の担い手となると思われますので、より一層引き続き環境づくりを進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問","question":"それとも、先ほどちょっと将来像みたいなのがちらっと出てきたのだけれども、将来八潮をどうしていくかというのに向けて、今八潮のまちをどうしていくかというのを考えているのか、それによって結構いろいろ変わってくると思うのだけれども、現状はどうなのか教えてもらってもいいですか。","respondent":"今井八潮まちづくり担当課長","answer":"したがって、新たな人材とかを発掘して、魅力的な八潮地域内の活動、例えば子ども向けのイベントを子育て世代の方主体で実施していただく、その活動がどんどん広がっていって有名なものになってくれば、八潮地域外から参加してくる方たちも出てくるといったところで。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"確認","question":"分かりやすかった。ということは、今の、要は住んでいる人たちがどうやってまちで持続可能的に生活ができるようになるか、プラス、ほかのところから八潮団地に流入してもらって、さらに今の八潮団地を盛り上げていくというのが、今品川区が取り組んでいる施策ということでいいですね。もう一回確認します。","respondent":"今井八潮まちづくり担当課長","answer":"委員ご指摘のとおりです。外から見ても八潮のまちが魅力的なものになっていって、それによって、人口の、高齢化の部分とかというところにも、少し解決策が見えてくるような取組ができればなと考えております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"年齢的に僕と大体同じぐらいなのです。さらに、これを１つのモデルケースではないけれども、していただきたいのは、例えば、今どんどん大崎、五反田地域だったり、東品川エリアでマンションが乱立していて、いわゆる昔の団地ではないけれども、それに近いマンション群があって、これはそれこそ４０年後はどうなるのといったときに、僕がディベロッパーとかと話をすると、彼らは正直建てて終わりなわけですよ。","respondent":"今井八潮まちづくり担当課長","answer":"集合住宅の中で、住み替えが進んでいくのかどうかといったところですとか、住み替えが進んだとすれば、地域活動が継続できるのかどうか、断続されてしまわないのかどうかといったような課題が出てくる可能性があるといったところで、八潮地域の中で、そういった状況に３０年。","voiceIndex":29,"id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"最初に１つお伺いしたいのは、去年つくられた八潮５丁目地区まちづくりガイドラインに、まちづくりの取組テーマが４つ挙げられていて、それのコンセプト、今回出された八潮地区のまちづくりコンセプトのような、ちょっと内容は異なるのですけれども、そういったちょっと似ているところもあったりして、ここの関連性というのはどうなってくるのかなというのをまずお聞きしたい。","respondent":"今井八潮まちづくり担当課長","answer":"昨年度、都市計画課のほうで策定いたしました八潮５丁目地区まちづくりガイドラインについては、都市計画ということで、ハード整備部門のほうで八潮のまちづくりを考えたときに、今後このような可能性があるのではないかというところを。","voiceIndex":33,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"そこも関わってくると思うので様々検討していただきたいのですが、今回ご報告いただいたところを見ていると、ほぼほぼ八潮の住民の方と、八潮に今関わっている方にしかお話を聞いていないのかなと思っていて、そうすると今石田しんご委員の質疑にあったように、現在しか考えていないように私には見えてしまったので、何か本当にもちろん八潮の今の課題を解決しつつ、八潮の将来に向けてというところと。","respondent":"今井八潮まちづくり担当課長","answer":"区全体の意見の聴取というところにつきましても、現状は、やはりどちらかというと八潮地域内、あるいはその近隣というところに視点が集まっているところもありますので、今後、全体の意見としてきちんとお声を聞けるような取組を検討させていただきたいと考えております。","voiceIndex":35,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"今年度の目標ということで、「具体的施策を検討し、実施に向け準備を進める」とあるので、もちろん現状の課題についての取組というのはぜひ早急にというか、進めていただきたい部分はあるのですけれども、将来に向けてのところはぜひゆっくり、ゆっくりというか、いろいろな方にご意見を伺いながら、品川区の地域バランスとかも考えながら、勝島とかも結構課題がいろいろあると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問","question":"農地なんかだと下で農業をしながら、発電をするという事例も起きていますので、夢を描こうと思えば、この方向性の夢もとてもいいと思うのですが、ちょっとほかで進められている検討と何となく飛び出してしまっているなというところがあったので、すみません、興味本位に聞こえるかもしれませんが、この方をセミナーの基調講演に選ばれた理由と。","respondent":"今井八潮まちづくり担当課長","answer":"八潮地域については、豊かな自然環境を有しているということで、そういった自然環境との共存というのが今後の課題というか、八潮の魅力を打ち出していく上でも、地域活動を持続可能なものにしていく上でも必要な部分だと認識しているところもございまして、例えば。","voiceIndex":39,"id":"exchange-016"},{"speaker":"吉田副委員長","kind":"質問","question":"これにつながるグループワークのときに、グループワークというのは、ファシリテーターがどなたかいらっしゃるのかなと思うのですけれども、そのファシリテーターの方が基調講演をうまくグループ討議に結びつけられるような仕掛けがあると、さらに発想が豊かになったと思うのですけれども、その辺も、コンサルタントとして環境エネルギー政策研究所が引き受けてくださったのか、その辺を伺えますか。","respondent":"今井八潮まちづくり担当課長","answer":"結論から言いますと、ファシリテートにつきましても、こちらの環境エネルギー政策研究所の主任研究員の山下さんにやっていただきましたので、グループワークについても、こちらの基調講演の内容に引き続いて討論をしていただいたというような内容になります。","voiceIndex":41,"id":"exchange-017"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"はい、分かりました。本当に、そういう意味ではすごくふさわしいコンサルタントであり、基調講演のお話をいただいた方だと思いますので、ぜひこれを本当に地域の方たちが元気になるような活動に結びつけていただけたらと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"}]},{"id":"topic-02","title":"臨海部広域斎場組合施設整備基本方針","agenda":"臨海部広域斎場組合施設整備基本方針","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"着実に進めていただければと思いますが、幾つかお伺いしたいのですが、施設整備基金というのは、現在、組合のほうではどれぐらいたまっているものなのか、金額が分かれば教えていただきたいのと、再生可能エネルギーの活用など、脱炭素化に資する整備を検討するというのが増築施設の整備方針の１つになっておりますが、とてもそれは重要なことかなと思うのですが。","respondent":"築山戸籍住民課長","answer":"こちらで考え方を示させていただいておりまして、脱炭素化の実現に向けた取組としては、「蓄電池を活用した太陽光発電等の再生可能エネルギーの活用、建築物の高断熱化、省エネ型空調設備やＬＥＤ照明などの脱炭素化に資する整備について検討する」というところで。","voiceIndex":48,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後になりますけれども、これは高齢化に即して必要な改修だと思うのですけれども、それに付随した問題で、区内から臨海斎場へのアクセスが課題かなと思っていまして、よく聞くのですが、例えば大井町からしながわ水族館にはバスが出ていますが、大井町のほうから臨海斎場につながるようなバスなどについても、火葬炉を増やすというのは必要だと思うのですけれども。","respondent":"築山戸籍住民課長","answer":"現状としましては、葬儀会社のほうでマイクロバス等も出しておりますので、そちらをご利用いただいていると認識しております。","voiceIndex":50,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"３月に斎場のほうで調査していたというのは初耳でした。ちょっと勉強不足でしたけれども、タクシーで行かざるを得ないというような状況がかなり広くありますので、区民の火葬料に跳ね返すような形ではなく、もう少し私もきちんとどれだけ要望が強いかというのも聴取したいと思うのですけれども、区として独自に対策を講じるなど、検討していただければと考えていますので、こちらは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問","question":"私のほうから１点だけ、アクセスの件ですけれども、今のお話の中でも自家用車やマイクロバスが使われている現状ということで、今回この増築をする部分が北側の駐車場を潰すということで、駐車場のキャパシティといいますか、そういったものは、実際見に行ってわりかし広いので大丈夫かなとは思うのですけれども、駐車場の混雑とか、そういった利便性のほうは、一応検討はされているのでしょうか。","respondent":"築山戸籍住民課長","answer":"現状ですけれども、北側駐車場が８５台、南側が１６４台の車が止められる状況になっておりまして、今回工事する場所が北側になりますので、そうしますと８５台分が新しい施設によって潰れる形になりますけれども、ただ臨海斎場から聞くところによると、現状。","voiceIndex":54,"id":"exchange-022"},{"speaker":"おぎの委員","kind":"意見","question":"どうしてもちょっと離れたところにあるので、バスや車などの利便性などをしっかり考えていただいているということで安心いたしました。使いやすいようによろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。今、安藤委員の質疑の中でマイクロバスを活用されているというのだけれども、マイクロバスというのは大井町の駅から出ているのですか。その経路がどういう経路になっているのか教えてください。","respondent":"築山戸籍住民課長","answer":"マイクロバスを利用の場合、葬儀会社が直接手配しますので、葬儀会場から火葬場という形になります。もしくは、式場を臨海斎場とする場合は、ご自宅から臨海斎場というような利用をされるかと思います。","voiceIndex":58,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"大井町や品川区側からなかなか行きづらいという話なので、マイクロバスというのは、また別の用途ということですか。安藤委員が言ったのは、品川区側からはなかなかアクセスが悪いので、どうしたものかなと。それには、例えばしながわ水族館にもバス便が出ていたりするので、うまくそういうのも活用できないのかなというのもあるのではないかなと思うのだけれども、その辺、改めてちょっと教えてください。","respondent":"築山戸籍住民課長","answer":"最近家族葬が増えてきておりまして、そういったケースは、ご家庭からマイクロバス、もしくはタクシー、自家用車等で乗り合いでいらっしゃるという形になっておりまして、一方、お通夜等で利用される方につきましては、これはまた先ほどの回答とはちょっと変わってきますけれども。","voiceIndex":60,"id":"exchange-025"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"分かりました。要は、利用者側の利用する事柄によって移動手段というのは違うわけで、家族葬の話は、それはその人たちのあれだから、それはまた別なのだよね。多分安藤委員が言っていたのはそうではないと思うのだよ。通夜とか、そちらのほうの話をした。そういうのも含めてぜひ利便性向上の検討をしていただきたいなと思うので、そこは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-026"}]},{"id":"topic-03","title":"品川歴史館リニューアル特別記念展「品川の海に御台場ができるまで」","agenda":"品川歴史館リニューアル特別記念展「品川の海に御台場ができるまで」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ＳＮＳですとか、もう既に発信していたら、ちょっと失礼ですけれども、あるいは「ハタチの龍馬」などにも発信していただくとか、そういった工夫があるとさらに多くの方に来ていただけるのかなと思うのですけれども、そちらについて、お考えなどがあれば伺わせてください。","respondent":"大森文化観光戦略課長","answer":"ＳＮＳとかそういったものへの掲載も随時検討してまいりたいと思います。","voiceIndex":67,"id":"exchange-027"}]},{"id":"topic-04","title":"しながわシティランのボランティア募集","agenda":"しながわシティランのボランティア募集","exchanges":[{"speaker":"ゆきた委員","kind":"質問","question":"一般的なマラソン大会では、多くはボランティアの証明書が発行できることが多いと思いますけれども、しながわシティランではボランティア証明書は発行できることになるのか、１点だけお聞きできればと思います。","respondent":"三井スポーツ推進課長","answer":"ボランティア証明書につきましては、大会後に希望する方に対して配付することを予定しております。","voiceIndex":74,"id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"根本的なボランティア精神からすれば、必要ないのかもしれないですけれども、就職活動とか、あと大学受験とかで、社会貢献意欲や協調性を示す証明にもなると思いますので、ぜひスムーズな、また証明書発行についてもスムーズな入手ができるような形でお願いできればと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-029"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。","respondent":"三井スポーツ推進課長","answer":"は応援といった中で、会場とかで何か参加できるようなことは実行委員会の中で協議してまいりたいと思いますが、まずは応援のところで参加していただきたいなというのが一番こちらとしては考えているところです。","voiceIndex":77,"id":"exchange-030"},{"speaker":"石田（し）委員","kind":"意見","question":"例えばゼッケンを渡すとか、そんなに難しくない作業が幾つかあると思うのです。みんなに、子どもたちも入れてあげられればいいなと思うので、ぜひそういった運営側にも何かしらできるものがあれば、やってもらえるといい教育の機会になるのかなと思うので、ぜひ検討していただければなと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-031"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、品川区民芸術祭との関係というのは何かあるのですか。その期間中ではないですか。それなのに一切見当たらないのだけれども、その関係性があれば教えてください。","respondent":"大森文化観光戦略課長","answer":"こちらはできたのが３年前ということで、そこの芸術祭の枠に入れていくかどうかというところは、今後の検討課題というところではあるのですが、品川区民芸術祭のほうは、文化振興事業団のほうと連携してやっているところもあるので、その辺りを今後調整しながら。","voiceIndex":88,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"デフリンピック啓発イベントですが、「あつまれ！えばら」と同時開催というところで、会場も重なるということですが、やはりデフリンピックがあるということ自体がまだまだ知られていないと思いますので、こういうイベントというのはすごいチャンスだと思いますので、先ほど「あつまれ！デフリンピック自体がすごいチャンスだという思いがあるのですが、いかがでしょうか。","respondent":"三井スポーツ推進課長","answer":"「あつまれ！えばら」のチラシは、現在作成中です。今日はちょっと間に合わなかったのですが、今連携しておりまして、「あつまれ！えばら」のチラシに入れていただく方向で調整をしております。","voiceIndex":93,"id":"exchange-033"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"高橋（伸）委員長","kind":"質問・要望","question":"これは先ほど申し上げましたけれども、サイドブックスのほうに掲載しておりますのでご確認ください。笠松刑務所です。次に、視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言いただきたいのですが、先日もお伝えしたとおり、各視察先より、質問事項の事前送付の依頼があります。現時点において、視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"広島のところで、来年東京ではありますけれども、デフリンピックがあるということで、デフスポーツについて、普及などに力を入れているところについて、やっぱり伺いたいなです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6831#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":33763,"voices":100}},{"id":"r06-20240925-7","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"ひがし委員","kind":"確認","question":"私からは、障害者支援課の所管施設分のところの２ページでまず１点、確認となります。こちらの心身障害者福祉会館の件なのですけれども、自立訓練について、高次脳機能障害の利用が増えた理由をどう分析しているのかというところと、逆にその他の障害の利用が進んでいないというようなことも書かれているのですが、利用促進に向けた取組、また今後の課題についてお聞かせください。","respondent":"松山障害者支援課長","answer":"そういった意味では、非常に高次脳機能障害の方がスムーズに行けるところ、つながるところができて、非常に評価をしていますが、ただし高次脳機能障害以外の方についても門戸を広げていきたいというのが、心身障害者福祉会館の指定管理者の意向でございまして。","voiceIndex":8,"id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ほかの障害にも門戸を広げてくださるということだったので、ぜひ利用促進に向けて取り組んでいただきたいと思います。次に、２５ページからの品川区立障害児者総合支援施設ぐるっぽの件から幾つか質問させてください。医療的ケアが必要な利用者の受入れをさらに進める必要があるということでしたが、先ほど１名の受入れをしているというご説明があったと思います。","respondent":"松山障害者支援課長","answer":"訪問系サービスの内訳です。居宅介護が年間で６７２件、それから重度訪問介護が１１９件、同行援護が８件、行動援護が０件、それから移動支援が６４９件です。","voiceIndex":10,"id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"少し聞き方を変えます。子ども発達相談室だと１,０００件減っていて、その下の相談件数、これは一般相談ですか。これについては、１日に複数件の相談ができる体制を構築し、円滑に親子面談へつなげたという前向きなことが書かれているのですけれども、相談としては減っているので、その件についてどのように分析をしているのかというところを聞かせていただければと思います。","respondent":"松山障害者支援課長","answer":"１点目、どのような医療的ケアまで対応できるのかというところですけれども、その方によって医療依存度等健康状態が違いますので、一概には申し上げられませんが、先日人工呼吸器の方はぴっころのほうで受入れを行っておりますし。","voiceIndex":12,"id":"exchange-003"},{"speaker":"ひがし委員","kind":"確認","question":"１点だけ。最後の相談件数のところ、子ども発達相談室だけでなくて相談件数、その下に書いてあるところについての減の理由を確認していると思うので、そこについても聞きたいのと、あと、今言っていた統計上、カウントの仕方が違うというところをもう少し詳しく教えていただければと思います。","respondent":"松山障害者支援課長","answer":"それは利用者ではなくて関係機関からも１カウントしていた分、特にその実際の実績として電話件数までカウントする必要はなかったので、現在の法人と区が協議して、実際の相談件数に見直したということになります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"ひがし委員","kind":"意見","question":"この減っている理由というのも、先ほどご説明いただいたとおりカウント数の数え方の違いだというところでよいのだったら、その認識が合っているかどうかも併せて聞かせていただければと思います。","respondent":"松山障害者支援課長","answer":"失礼いたしました。子ども発達相談の下の相談件数、一般の相談件数につきましても、同じようにやはり電話を１本取るたびに１件と数えていたところを、実際の相談件数でカウントしたということになります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"ひがし委員","kind":"意見","question":"理解をいたしました。最後に、この初回待ち時間の長期化を解消するためにと書かれているのですけれども、現在の初回の面接に向けて待ち時間、期間というのはどのぐらいあるのかを最後にお聞かせいただければと思います。","respondent":"松山障害者支援課長","answer":"子ども発達相談室の初回待ちというのは、今現在は解消しております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"それで、障害者のほうから伺いたいのですけれども、まず、１ページの心身障害者福祉会館なのですけれども、心身障害者福祉会館は１億９,５２３万円ということで約２億円程度の指定管理料が出されていますけれども、これは多分地域生活支援事業だったりとか、そういうので法内で全部が来るというだけではないものもされているのかなと思うのですけれども、これだけの指定管理料を出すその中身。","respondent":"松山障害者支援課長","answer":"指定管理事業の中身ですけれども、人件費が主なものです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"２５ページのぐるっぽのところなのですけれども、２６ページのほうになるのですけれども、この指定管理料が令和３年度、令和４年度、令和５年度とどんどん上がってきているのですけれども、特に令和４年度から令和５年度にかけての指定管理料が１.５倍に上がっていて、令和３年度からすると約２倍に指定管理料が上がっているのですけれども。","respondent":"松山障害者支援課長","answer":"２７ページの区民満足度の視点ですけれども、区としては指定管理３年目にどの施設も実施するということになっておりまして、こちらの現指定管理者においても、評価というのは高いものとなっております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"あと、ここでかなり利用率が下がっていると思うのですけれども、児童発達支援も下がっていますし、放課後等デイサービスも３７.１％ということで、令和３年度からするとかなり下がってしまっているという思いがしているのですけれども、先ほどの相談のほうは件数のカウントの仕方だということで分かったのですけれども、例えば放課後等デイサービスとかは。","respondent":"松山障害者支援課長","answer":"次に児童発達支援と放課後等デイサービスの利用率の減少についてです。こちらは感染症等の影響から、利用率がかなり下がった時期があります。次に、就労継続支援Ｂ型についてです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"南品川障害児者相談支援センターなのですけれども、区の地域生活支援拠点ということで、緊急時の受入れ対応が求められていると思いますが、どの程度の緊急時の対応を実施できているのか。２４時間の電話対応というのを以前はされていたと思うのですが、現在はどうなっているのかについても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"そういった場合が本当に緊急時というところになります。ほかに支援できる方がいないといったときに対応しています。２４時間というのは、連絡が入れば法人のほうにも連絡がつくようになっていますので、法人のほうで対応をしています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"引き続いて、最後のほうを伺いたいと思うのですけれども、介護ではまず２ページなのですけれども、総合事業利用の方を受け入れたことによって、単価が安くて事業所として大変だというのが幾つも出てきているのですけれども、これは総合事業が入るときに総合事業の単価が低いというのは大きな問題になっていたと思うのですけれども、この総合事業というのは区独自に決めている単価だと思うのですけれども。","respondent":"菅野高齢者福祉課長","answer":"区としては委員もおっしゃられたとおり、今年度から居住支援手当のほうを支給させていただいて、まだちょっと今手続きのところでちょうど受付を開始したところということもありますので、それによってどのように人材確保が解消されていくかというのは。","voiceIndex":29,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの１４ページのところで、光熱水費の高騰によって増加しているということも書かれているのですけれども、やはりその光熱水費の高騰というのはどの事業所にとっても大変かと思うのですけれども、これについては区としてはどういう対応がされているのか、その点も伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今年度につきましては他の自治体の動向等も見ながら、今までは国の支援金、新型コロナウイルスの臨時交付金があったので、それを使わせていただきながら、そういった物価高騰対策支援金を出させていただいておりまして。","voiceIndex":32,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"私から、高齢者福祉課所管分のところについて、幾つかお聞きしたいと思いますけれども、まずＩＣＴ機器の導入という文言が結構幾つかあったと思うのですけれども、今後の介護士とかそうした方の負担軽減のために、ＩＣＴ機器の導入を推進していく必要があると思うのですけれども、現在どの程度そのＩＣＴ機器を導入されているのか、どのぐらいの割合で進んでいるのかをお聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今年度、平塚橋特別養護老人ホームのほうで進めさせていただいているのですけれども、例えばおむつの量が分かるようなＩＣＴ機器というかその機械があって、それをリモコンで飛ばして分かるというので、夜間のおむつの交換の時間が少し業務改善にもなるし。","voiceIndex":36,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"７２ページだとか４４ページとかに、特定技能外国人の採用により事務費が増加しているとか、あと外国人職員向けマニュアルとか、外国人についての記述があるのですけれども、大体外国人の職員の方というのはおおむねどのぐらい採用しているものなのでしょうか。その現状が分かればお知らせください。","respondent":"菅野高齢者福祉課長","answer":"この７２ページのところで、これは三徳会のところなのですけれども、三徳会は積極的に令和４年度以降外国人の採用を行いまして、現在１４人ほど勤めているとも聞いておりますので、恐らくその辺りの記述が平塚橋特別養護老人ホームのここの部分なので。","voiceIndex":38,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"高齢者福祉課のところの２３、２４ページになるのですが、総括の積極的に評価した事項のところで、「年度当初、看護師は派遣職員のみでの配置だったが、年度途中の採用活動により２名を正規雇用とし、人件費を大幅に削減した」とあるのですけれども、すみません、これは２３ページのところで人件費を大幅に削減したとなると、支出のところのどこが削られたのか、お教えいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘のとおり、この２３ページの支出の一番上の人件費のところ、前年度は７,９６１万円で、令和５年度が８,４４７万円ということで、人件費は５００万円ほど増えているけれどもこういう記載があるということで、恐らく多分、看護師の確保にすごく苦慮しまして。","voiceIndex":41,"id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"何となく分かったのですけれども、ただ、前提の問題としてお伺いしたいのが、この人件費、これは派遣職員で要は人材派遣会社を利用していたと推察されるのですけれども、これは一般的に一般企業だと、人材派遣の場合というのは外注費になって、人件費ではない気がするのです。その辺はどのように基準が決まっているのか、お教えいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"もしそうではなかったとしたら、多分ここの月見橋在宅サービスセンターのところも、事務費か事業費が物すごく令和５年度跳ねているというか伸びているはずですので、ここは人件費として計上しています。","voiceIndex":43,"id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"分かりました。一応確認ですけれども、ではこれは、全てのモニタリングの事業者に対して、派遣会社を利用した場合も人件費というように入れるということでお願いしているのかというのと、あと、これはどこまで人件費に。その辺の線引きをお教えいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"先ほど人件費のほうは派遣も含めて全てこちらのほうに入れさせていただいているとお話はさせてもらいましたが、法人によって多少の会計の振り分け方が違う部分もありますので、１００％そうだと言い切れないところもありますが、区としてはやはり分かりやすいように。","voiceIndex":45,"id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。別なのですけれども、少々要望にも近いかもしれないですけれども、今後こういったモニタリングをする上で、何か離職率みたいな毎年の経年の数字みたいものをもし出していただけたらと思うのですが、そういったところは既に調査というか、モニタリングで毎回事業所から提出というのはされていらっしゃるのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"例えばすごく小さい事業所もあったりとかしますし、毎年それで例えば何人か辞めたら急に離職率が上がるとか変動もあると思いますので、その辺りは難しいかなというところで、離職率については５年に一回、非公募であれ公募であれ選定のほうをしますので、そこでは法人全体。","voiceIndex":47,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちょっと近い話なのですけれども、品川の福祉専門学校の卒業生の方がどれだけ入職されて、もしくはその中で離職をされたみたいな、そういったデータというのは取ってあったり、もしくはそういった掲載を入れるというのは可能なのかどうか、その辺もお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"３年から先については、例えば３年以内だと奨学金を返さなくてはいけないとかそういう話になるので、学校のほうで連絡が来て、うちのほうにも連絡が来て、そういう奨学金の返還をしてもらうとかいうので数字をかなり把握しているのですが。","voiceIndex":49,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。これはちょっと要望ということで、ひとまず、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"あと最後は、これは６２ページのところで改善が必要な事項というので、「週３回入浴への調整と定着」ということで書かれていまして、これは基本週２回ということになっていると思うのですけれども、それを３回に挑戦というのはもうすばらしいと思いながらこれを見させていただいたのですけれども、これをぜひできるような方向で評価して、ほかにも勧めていただきたいと思っているのですが。","respondent":"菅野高齢者福祉課長","answer":"４点ご質問いただきましたので、順番にご説明していきたいと思います。","voiceIndex":53,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１点だけ、高齢者のほうの２ページのところで、総括の八潮団地の特殊性というところなのですけれども、これでエレベーターがないところの玄関まで送迎ということなのですけれども、それでそのほかに、事業所から送迎車の駐車の場所とかスペースとか、そういったことについての何か記載というか、報告みたいなものがあったかどうか、もしあれば、ちょっとご説明いただきたいのですけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"ここの八潮団地については、多分それほど駐車スペースでいろいろとというのは地理的にはあまりないのかなと思うのですが、よく聞くお話ですと、ちょっと狭いところにお宅があったりとかして、長時間止めていると近隣の方から少し何か違法駐車ではないけれども。","voiceIndex":56,"id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"なので、当然これは各団地のルールというところでなかなか触れにくいところではあるかもしれないのですけれども、そういった送迎をしている介護事業者で困り事といいますか、そういう事情があるというのもぜひ所管として把握しておいていただければと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"１点だけお願いします。健康センターのところで１点伺いたいのですけれども、指定管理料が令和４年度から令和５年度に少し増えている理由を教えていただけたら。令和４年度で収支とかはそれほど関係性はないのかもしれないですけれども、結構たくさんここで指定管理料が増えて、その結果、差引き収支もかなり黒字が増えているのですけれども、この理由を教えてください。","respondent":"若生健康課長","answer":"令和４年度から令和５年度での指定管理料の増加についてですが、その前の令和３年度については、令和５年度とあまり変わらないような水準の約１.５億円となっていますし、実はこのコロナ禍が続いて、令和２年度、令和３年度、令和４年度までかかって。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"確認","question":"そうすると、令和５年度が２,０００万円を超えての黒字になって、令和６年度というのも同じような指定管理料になっているのか。その確認だけお願いします。","respondent":"若生健康課長","answer":"指定管理料、令和６年度につきましても、これは指定管理の更新があった関係で若干指定管理料が上がっているところは、人件費等の増加に伴ってあるのですけれども、指定管理料につきましてはほぼ同水準ぐらいに推移しているところであります。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。これからどういう状況になっていくのかというのを注視したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-026"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"なぜなら、八潮で行きたくないから人を頼むとその分単価が上がるのだとか、いろいろな話があって、いろいろな手も入れて頑張って行政側もやってきてくれて、その成果がやはり出るというのが、多分令和５年はまだ改善途中だったのかな。令和６年は大手を振って変わりましたと言えるようになってほしいと思っていて、そうなりますと言っていただけるのかどうか、そこだけ聞きます。","respondent":"寺嶋福祉部長","answer":"数字、結果を出さなければいけないというところは品川総合福祉センターも強く思っていると思いますので、できればここでそのとおりですと言いたいところなのですが、そうなるように鋭意取り組んでいることと、区もしっかり支援していることは間違いございませんので。","voiceIndex":64,"id":"exchange-027"}]},{"id":"topic-02","title":"令和７年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和７年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"実績を少し伺いたいのですけれども、令和４年度の募集で何人が応募して、令和５年度で何人入れたのか伺います。それから、去年の令和５年度の応募者が何人かも教えてください。","respondent":"樫村高齢者地域支援課長","answer":"令和４年度の実績ですが、６５名の方に登録いただきまして、入居された方が２２名いらっしゃいます。それから、昨年度につきましては、６２名の方に申込みをいただいているところです。","voiceIndex":75,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6829#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":43545,"voices":93}},{"id":"r06-20240925-8","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年１１月都営住宅入居者募集","agenda":"令和６年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"併せて伺いたいと思うのですけれども、以前に都営住宅だったか区営住宅だったかの入居の申込みの期間について、期間というか郵送の関係ですね、消印有効だったのが必着に変わっているというお話で、ちょっと議事録を調べてみたところ、議事録にあったのは２００８年だったのですけれども、そのときには郵送で消印有効まで受け付けていますということで答弁をされていまして。","respondent":"川原住宅課長","answer":"前回も申し上げた内容と大体一緒になってしまうのですが、皆様やはり高い倍率ですので、何回も応募していらっしゃる方が多いということ、そして、申込みの初日に列をなしてお待ちいただいている、それがやはり郵送ではなくて。","voiceIndex":9,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり今回の応募倍率を見ても、単身は特に５５倍ということで倍率が高くなっているということですので、都営住宅ですけれども、東京都に増設を求めていただきたいと思いますけれども、いかがでしょうか。区営住宅も同様に、ぜひ、やはりニーズが高いと思いますので、増設をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"一方で、民間住宅、空き家は、今後全国で９００万戸に達する勢いで、空き家だけではなく、空き室もやはり管理も必要となってくる部分もありますので、空き家対策というところと居住支援というところも含めて。","voiceIndex":11,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"空き家の問題は確かにありますので、民間の活用もよいのですけれども、やはり公営住宅の役割、特に福祉的な役割を発揮していただきたいと。そのためには増設をしていっていただきたいということで求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日もよろしくお願いいたします。初めに、応募倍率の説明がありましたけれども、質問者もいつも聞いていると述べているほど毎回聞いていると思うので、あらかじめ資料に載せていただきたいと思うのですけども、いかがでしょうか。","respondent":"川原住宅課長","answer":"今回こういったご意見もいただきましたので、研究の材料とさせていただいて、また、各区の住宅担当課長会等もありますので、他区の募集の内容の記載方法について等も併せて情報収集と研究をしてまいりたいと思います。","voiceIndex":14,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、都営住宅の増設の議論で、ストックがあるという理由で、都営住宅の増設を東京都に求めるのではなくて、別の言い方にすれば、区営住宅は自分たちで造るのではなくて、民間の活用をするという説明がありましたけれども、造るのではなくて民間の活用とする理由は何か、伺いたいと思います。","respondent":"川原住宅課長","answer":"一方で、民間に関しては、現に、例えば大家であるとか、不動産会社から、この空き室の活用というところも要望として直近でいただいているところもありますので、そういった民間の住宅の活用をすることによって、もちろん賃借人の方ではなくて、賃貸人。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"それはそうだと思います。その次に、庁内での協議が必要になってくるというところのご説明がありましたけども、これはどういう意味合いなのか、改めて伺いたいと思います。その優先順位を考えたときに、いわゆる公営住宅を造るのは、優先順位が低いという意味合いなのか、そもそも造るという考えがないのか、庁内での協議が難しいというところがどういう意味合いなのか伺いたいと思います。","respondent":"川原住宅課長","answer":"次の質問のまず１点目、庁内の協議が難しいであるとか、優先順位が下であるといったような考えは全くございません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"それと、区営住宅や都営住宅にならう家賃を把握しているのかと伺ったところ、団体の声では聞いているというお話はありましたけれども、つまりは戸数とか、家賃の金額とか、そういう実態を数字としては把握されてないということでよいのか伺います。これはいただけないなと思うのですけども、最後にいかがでしょうか。","respondent":"川原住宅課長","answer":"都営住宅の増設についてですが、現時点では、研究の一つとしてさせていただきたいと申し上げさせていただいているところなのですけれども、セーフティーネット法、法律の法改正の趣旨にのっとるというところももちろんありますし、民間ストックの有効活用を図っている。","voiceIndex":20,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと煮え切らない答弁だなとは思いますけども、一言述べますと、昨日も再開発について議論させていただきましたけど、ああいうタワーマンションは造るのに、低廉な家賃の、しかも単身の倍率が５５倍と求められている住宅については、いろいろ理由をつけて造るための具体的な行動を移さないというのは、住宅施策がゆがんでいると今までも述べさせていただきましたけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"今日は都営のものなのですが、区営もちょっと関連して。配布場所なのですが、この考え方というところをまず教えてください。対象がいろいろ、何向けとかあって、全世代だからというところだったのですが、この配布場所になっているということを教えてください。","respondent":"川原住宅課長","answer":"配布場所についての考え方というご質問であったかと思います。","voiceIndex":23,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"今の答弁を伺うと、例えば、今あるのかもしれないですけど、シルバーセンターは配布場所になっていないのですかね。配布場所になっていないという理由も含めて教えてください。","respondent":"川原住宅課長","answer":"そういったシルバーセンターの設置等も研究してまいりたいと思います。ご意見ありがとうあります。","voiceIndex":27,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"前回の別のときに、冊子が残っちゃうとか、紙の問題とか、そういう視点でもちょっと確認させていただいたのですけど、あとは今ご答弁いただいたような形で、比較的私たちもご相談いただく場合って高齢世代の方が多いかなという認識はあるのですけど、そう考えたら、比較的そういう世代の対象の施設であるシルバーセンターを配布場所として置くというのは、一定の効果というか、当然。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"}]},{"id":"topic-02","title":"令和５年度指定管理者による管理に対するモニタリング・評価","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"昨年聞いたところ、５年に一度の契約のときにはやっているというお話だったのですが、その後は適宜やっているということで、この労務関係のチェックは常にやるべきではないかと思います。こうしたモニタリングの機会を利用しながらやっていくということが必要だと思うのですが、いかがでしょうかというのと、それぞれの労務関係の状況を伺いたいと思います。","respondent":"川原住宅課長、中西環境課長、山下交通安全担当課長","answer":"細かな視点、指摘事項があったものについては、継続して月１回の各社との定例会で確認を取らせていただくなど努めているところです。昨年度もご答弁申し上げたとおり、随時確認をしているといったところ、それから今、住宅課長が答弁申し上げましたが。その他の法令違反等につきましては、特に報告は上がっておりませんが、引き続きそういった労務のチェックは担当者を通じても。","voiceIndex":36,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で法令違反はないということでしたけれども、株式会社品川宅建管理センターのほうは大きな違反はなかったということは小さな違反はあったのかなと思ったのですが、あったのかどうか確認させていただきたいのと、これは全てに通じますが、法令違反がなくても。","respondent":"川原住宅課長","answer":"株式会社品川宅建管理センターに関しても、法令違反があるレベルに達しているという事例はございませんでした。一部、提出期限漏れの書類の提出があったところの指摘があったところが減点となってございましたが、特に法令違反等はございません。","voiceIndex":40,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。夜９時までやっていますので、そうした中で大変だろうとは思っていたのですが、どういう状況だったのかというところを伺いたいと思います。あわせて、ボランティアの方がいらっしゃるということで、今何人いらっしゃるのか、シニアボランティア、学生ボランティアなどがいらっしゃるということなので、その内訳も分かれば伺いたいと思います。","respondent":"中西環境課長","answer":"ボランティアです。内訳が手元にございませんが、全体で１９名のボランティアの方にご登録をいただきまして、例えば、エコルとごしの森の探検ツアーですとか、講座ですとか、あとはエコルフェスのイベント等で従事をいただいているといった状況です。","voiceIndex":42,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"来館者が多かったということで２名の増員ということですけれども、当初の３万人から２０万人と見ると約７倍の方が来ているという中で、２名の増員だけで大丈夫なのかなと思うのですが、いかがでしょうかというのと、ボランティアの方は１９名ということで、職員の方が大変な中でボランティアの方も支援をされていて、ボランティアの人も大変な状況になっているのではないかと思うのですが。","respondent":"中西環境課長","answer":"先ほど申し上げましたとおり、毎月の定例会議等で本社の人間、エコルとごしの職員と会話を続けておりますので、その中で体制が組めるところに関してはこちらでも対応してまいりたいと考えています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"状況としては、体制としては整っていると聞いているというお話でしたけれども、ほかのところでも退職者が出たというところで、シートにも書いてありましたが、この要因、労働環境に起因するものなのかどうかというところも伺いたいと思います。それとあわせて、昨年度、令和５年度の講座はどういったものをやられてきたのか。いかがでしょうか。","respondent":"中西環境課長","answer":"なので、例えば５月、６月の時点では空調をそんなにかけずに地中熱の冷えた空気で足元が涼しくなる、空調を使わなくても快適な環境が保てるといったところで、こういった削減率になっていると認識しています。","voiceIndex":46,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、講座のところでは様々な講座をやられているということで、広く区民の方が環境問題を考える場になっているのかなと思うのですが、私の一番の関心は地球温暖化のところで、先ほどもお話ししましたが、やはり今、気候危機と言われるほど大変深刻な状況になっているということで、区民としてもそれに力をお貸しいただくということも必要ですが、そもそも国の姿勢が後ろ向きになっているということで。","respondent":"中西環境課長","answer":"区としても、新改築をする場合にはＺＥＢ認証を１つ目指すといった形になってありますので、引き続き施設整備課、それから学校施設担当とも連携しながら進めてまいりたいと考えています。それから、講座のところで、いわゆる地球温暖化といったお話です。","voiceIndex":48,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"地球温暖化の講座はしているということで、それはもちろんやっていただきたいと思うのですが、やはり日本が世界から立ち後れた状況にあるということもお知らせいただいて、日本もＣＯ２の排出が世界でも５位というところですから、そこを改善していかないとこの気候危機も改善していけないということになると思いますので、そうしたことも含めて講座をやっていっていただきたいと。","respondent":"川原住宅課長","answer":"２点ご質問いただきました。１点目の滞納者の人数というところでは、毎月滞納者リストで確認をさせていただいているところです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたら、人数のほうは後でお答えいただきたいと思います。なかなか長期に待っているという気がしますけれども。特にこの滞納者のところは福祉関係にもつなげているということですけれども、ぜひそうした滞納者の大変な状況をつかんでいただいてつなげていっていただきたいと思うのですが、実際にどういった形でつなげてきたのかというところが分かれば伺いたいと思います。","respondent":"川原住宅課長","answer":"主に区民住宅はそういったケースは少ないのですが、区営住宅においてはもともと困窮者、低所得者の方がお住まいになられる住宅ですので、そもそもの家賃の使用料といっても非常に低廉なのですが、その中でも、例えば年金の月額がかなり限られている中で。","voiceIndex":52,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活保護のほうもつないでいただいているということで、ほかにも保険料ですとか税金ですとか滞納している可能性もありますので、そうしたところもしっかりと福祉関係にもつなげていただいて、暮らしていけるように支援していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。ファミーユのところですけれども、計画的、効率的な修繕や設備更新等を行っていくことで工事費用の増加を引き続き抑える必要があるということで、修繕や改修計画などの長寿命化計画を定めて、保全ですとか予防ですとか修繕を区としては実施していて、それを引き続き行っていくということだと思うのですが、現在の状況について確認させていただけたらと考えています。","respondent":"川原住宅課長","answer":"令和５年度に実施したものではなくて今年度実施する予定ということでよろしいでしょうか。令和６年度も同様に、長寿命化計画、計画修繕に基づいて項目を、まずは指定管理者のほうから出していただいたものを、この課内でも精査をして予算要求をしています。","voiceIndex":55,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろ計画していただいて進めていただいていると思うのですけれども、緊急的なものがあったりしますとそれだけ時間がかかってしまったり、経費のほうもかさんでくるかと思いますので、今また情勢等も様々変わってきていますので、そのときのタイミングで指定管理者と区等で相談していただきながら、また、入居者の方のお声も聞いていただきながら、計画のほうも見直ししたり。","respondent":"中西環境課長","answer":"実際、もともと入っていただいた方は、先ほどご答弁申し上げた中にもお話をしましたが、お子様と触れ合うことが楽しいと思っていただける方ですとか、あとは災害ボランティアみたいなことをやりたいといって入っていただく方もいますので。","voiceIndex":57,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"それぞれご説明ありがとうございました。もう１点、外国語対応のスタッフを配置しているということですけれども、外国人利用者の方はどこの国の方が多くいらっしゃるのかなと思いまして、来館者は何語をお話しになられる方がどのくらいいらっしゃって、国の傾向とかがもしありましたら教えていただけたらと思います。","respondent":"中西環境課長","answer":"来館者の中でどういった国籍の方がいらっしゃるかというところまで、定数的に取れているものがございませんので、ただ、英語がしゃべれるスタッフのほうで対応させていただいているところです。","voiceIndex":59,"id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"時代によっていろいろなことが変わってきたりですとか、特にコロナというのがあったので、在宅ワークの方が増えた時期もこれまであったかと思うのですけれども、またこれからも、自転車の駐輪場が定期、当日と利用されていくのかは、既に一定ではないというところであると思いますので、バランスについて、年単位で見ていくのか、月単位なのか、数か月単位なのかというところで。","respondent":"川原住宅課長","answer":"滞納については日々流動的ですので、そこの点をご承知おきいただきたいのと、あとは現時点で判明しているのが８月末時点での滞納者の世帯数という形でのご答弁となります。区営住宅においては１７世帯、区民住宅においては５５世帯という形になってあります。","voiceIndex":63,"id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"品川宅建管理センターのほうですけれども、この中でお声として伺ったので確認ですが、南大井５丁目は特にですが、２ページ、評価の視点別のコメントのところの予算執行、財務の視点ですが、これは西五反田のところとほぼほぼ一部文章が一緒ですけれども、予算の範囲内で適正な維持、管理を実現と記載はあるのですが、南大井５丁目で地域の方から伺うと、お風呂とか配管ですかね。","respondent":"川原住宅課長","answer":"都度、巡回等で必要な箇所を確認していただいている状況にはなるのですけれども、確かに今おっしゃっていただいた南大井の住宅であるとか水回りについてのご要望は、区民の方のみならず指定管理者との定期的な打合わせの中でもお話はいただいているところでございまして。","voiceIndex":65,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"指定管理者のことですが、３か月ぐらいかかる、ここは区民住宅です。当然、入居者のお考えだとかが大事だと思うのですが、施設維持、水回りの劣化状況がどのぐらいなのか、この辺りはどういうお考えでしょうか。","respondent":"川原住宅課長","answer":"最終的にはその方はそこにとどまるという選択をされたところではあるのですけれども、引き続き区民住宅ですので、それなりの使用料をお支払いいただいているところですので、今後も適切な施設運営および維持管理というところでは検討してまいりたいと考えています。","voiceIndex":67,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"ぜひ検討していただいて。まとめて聞けばよかったのですけれども、そのぐらい期間がかかってしまいますよ、ちょっと一回退いてもらいますよという話は、それぞれの該当する方には、既に話としてはずっとされているという理解でよいですか。","respondent":"川原住宅課長","answer":"今こちらで申し上げたケースと、委員がおっしゃっていたケースが同一人かというところは後ほど確認させていただければと思いますけれども、私のほうで報告として把握しておりますところには。","voiceIndex":69,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"根本的な修繕というか、ここが大事だと思うので、それに必要なことは、まずお知らせだったり、またそれに係る対策というのはしっかりと検討いただきたいと思いました。予算執行のところ。これは定期利用のところを使ったから１００％を超えているという意味ですか。令和５年度については決算書を見れば分かったのですけれども、年間の使用料は全部で幾らになっているか教えてください。","respondent":"山下交通安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"そうすると、指定管理者の数字、１ページ目の収入指定管理料というのは、指定管理者、ＮＣＤの収入ということなので、２億３,８４３万円。区の収入が２億６,０００万円余ということなので、そうすると、駐輪場の区としての運営という部分ではうまくいっているという理解でよいですか。","respondent":"山下交通安全担当課長","answer":"これだけを見ますと確かにそのとおりですが、放置自転車対策につきましては、撤去ですとか指導、警備、こういったものに対する委託料ですとかその他工事ですとか、そういった費用がかかってまいりますので、全体からすると１００％ではないですけれども、こちらに記載あるとおり。","voiceIndex":73,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"先ほどの定期利用と当日利用で、場所の活用の仕方というか、もったいないというか、定期利用が５０％とか６０％とかそのぐらいで、先ほど定期利用ところもご案内しているよとあったので、その辺のインジケーターをどっちにするか。定期利用の台数と当日利用の台数を増やす。こういう視点ではいかがですか。","respondent":"山下交通安全担当課長","answer":"駐輪場の効果的な利用というところで、やはり空いているところは有効に使っていくことは当然ですし、また、困っている方がいれば、１００％以上に達していて満車である場合に案内することによって、少しでも区民の利便性も上がり、さらに区の歳入にもなるというところでは。","voiceIndex":75,"id":"exchange-030"},{"speaker":"つる委員","kind":"意見","question":"全体の中で売行きのよい事業でしっかりと歳入を増やして、経費がかかるところにしっかり充てていくということは、これは全体の大きな事業、くくりの中でも見ていくということが大事なのかなと思って、もうけるとかそういうことではなくて、いかに歳出に充てていくお金をこの事業の中でしっかりと持っていけるかということも、それは当然利便性向上というのが必須である中で。","respondent":"山下交通安全担当課長","answer":"大変申し訳ありませんでした。","voiceIndex":77,"id":"exchange-031"},{"speaker":"つる委員","kind":"質問・要望","question":"その訂正の下で、であるならば、むしろどれだけもう少し利用料で増やしていくかということも、これは努力として、これはこれで必要。あくまでも利便性が低下するようなことは駄目だけれども、そういう中でいかに売上げを上げていくかということも、これは指定管理の方ともしっかり協議しながら、区としても、先ほど指導とあったわけですけれども、していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-032"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"塚本委員長","kind":"質問・要望","question":"初めに私から視察先をご紹介します。次に、視察先で特に質問や確認したい事項、ご要望について伺いますが、既に視察先より質問等があれば事前に伺いたいとの依頼があり、各委員、本日の勉強会の資料等を参考に、視察先について調べていただきまして、質問事項を出していただきたいと思います。視察先について、この場で質問、確認したい事項、ご要望等がございましたらご発言をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"１点だけ、セーフティーネット住宅のところで、専用住宅があるのかどうか、どういう形になっているのかというところで、そこが結構いろいろなところでも課題。昨年視察で行った自治体でも、専用住宅はたしかゼロ。品川区もゼロということですので、そこのところをお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"私も住宅セーフティーネットのところで、特に子育て世帯ですとか母子家庭であったり、離婚を検討中の方、ＤＶ被害者の方、そういった方への支援をどうやっていらっしゃるのかというところを詳しくお伺いできたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6827#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":37804,"voices":91}},{"id":"r06-20240925-9","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"文教委員会","time":"午前１０時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区教育振興基本計画（素案）に係るパブリックコメントの実施","agenda":"品川区教育振興基本計画（素案）に係るパブリックコメントの実施","exchanges":[{"speaker":"田中委員","kind":"質問","question":"幾つかありますが、今回、この素案に関してのパブリックコメントを行うという報告でありますので、教育ビジョンの中身についてのやり取りは大丈夫ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど微修正があるというお話でありました。パブリックコメントの結果や、当然、寄せられた内容にもよりますが、コメントの内容によっては、この素案自体の修正ということも可能なのかどうかという確認です。こちらも内容によると思うのですが、我々の意見が素案を修正するに足る内容であれば、修正ということも可能なのかどうか。その位置づけをお聞かせいただきたいと思います。","respondent":"舩木庶務課長","answer":"先ほど、微修正と申し上げましたのは、パブリックコメントに付すまでの間に、注釈といった部分での内容の変更があることをご説明をしたところです。パブリックコメントの目的は、広く区民の方に周知し、そして、いろいろなご意見を頂くことと認識しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"少しお伺いしたいところがあります。最初の委員会のときも少し触れたのですけれども、私はまだ若月世代でございまして、教育改革の「プラン２１」がベースとなっていて、その後、「品川教育ルネサンス」。まだまだいろいろあるのですけれども、まず、子ども中心のビジョンであるべきだと思っていますが、そのことについてのご意見といいますか、受け止めをお聞かせいただきたいと思います。","respondent":"舩木庶務課長","answer":"ご指摘の２３ページにつきましては、まさに、品川区がこれまで進めてまいりました「品川教育ルネサンス」で示されている３つの基盤をしっかりと活かした上で、さらに、今後、どういったものを目指していくのかということを描くビジョンとして捉えていますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ子ども中心でお願いします。地域の力を得ることの良さはいろいろあると思います。地域の歴史的な資源を学ぶための教材というか、教えてくださる地域の方の協力は当然必要で、それを全否定するわけではないのですが、地域の力を得ないといけない、地域の力を借りないと学校教育が成り立たないと捉えられてはいけないと考えています。その検証についての今の受け止めをお聞かせいただきたいと思います。","respondent":"舩木庶務課長、中谷指導課長","answer":"今、委員のご指摘、ご意見のように、児童・生徒や保護者の方のアンケートなどをとっていく中で検証をというところですけれども、振興基本計画の狙いとしては、まずは、区立の小学校、中学校、義務教育学校の段階から。そこもしっかり支えていきながら、第２世代の品川区の教育ということで進めていきたいと思っています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"後段の部分はいいお話をお聞かせいただきありがとうあります。ぜひ期待をしております。ぜひ検証のほうも受け止めていただいて、進めていただきたいと思います。もう少しいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"もう一つ言うと、１７の目標に対しまして、ここで向けているのは２と６と１４と１５が抜けているのです。１４、１５は、環境に対しての目標ですので、環境学習ということは、私は大切なことだと思っているので、そことの関係性もしっかりつなげていくべきだと思います。すみません。３６ページ、３７ページでのＳＤＧｓ関連について、受け止めはいかがでしょうか。","respondent":"舩木庶務課長","answer":"そういった中で、ＳＤＧｓ、開発目標というのは非常に考え方が広いですし、世界的な部分でもありますので、その部分については、本計画が示すことによって進んでいくであろう教育、いろいろな教育施策などの部分が、果たしてＳＤＧｓとどうなっていくのか、あるいは。","voiceIndex":16,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"かなり新しい考え方が入られたのかなと思います。区長がよくおっしゃられるウェルビーイングの教育。その中で若干伺いたいのですけれども、２６ページ、２７ページの今回特筆すべき点として、ポンチ絵がこちらのレジュメにもあるのですが、「学びの羅針盤」２０２３というところです。２７ページの「ＡＡＲサイクル」に基づいた学習プロセスの活用。そこを、まず１点、伺いたいと思います。","respondent":"舩木庶務課長","answer":"そういった中で、本計画がしっかりと示せる形になった際には、教育現場もそうですし、児童・生徒一人ひとりに対しても、区が目指す方向性はこのようなことなのだと伝えることについては、しっかりと検討を進めていきたいと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"確認","question":"それについて、また何かあればご意見を伺いたいのですが、３４ページの方針８のところで、「社会・経済状況によらない教育の実現」の手法のところに、いわゆる経済的理由や社会状況により就学の機会が損なわれることなく、すべての子どもたちが平等に質の高い教育をというところで、給食費や教材費の無償化、災害時における教育活動の継続に向けた体制構築があります。ごめんなさい。","respondent":"舩木庶務課長","answer":"ご質問の３４ページ、方針８に見受けられますように、給食費や教材費の無償化という具体な部分を、このような体系的に施策推進の方針という形で示したのは、本計画が初めてだと認識しております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"将来的にと言う前に、子ども自身が学校教育、学校生活の中で、品川区の児童・生徒の段階でそういう能力を身につけて、共生社会をつくるということが、ＯＥＣＤより先の品川区の大きな目標ではないかというご発言があり、大変すばらしいご意見だと思って、そういったこともきっとこの計画の中には入っているのだと思うので、また別の機会にお尋ねします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"１点、パブリックコメントの閲覧場所なのですけれども、これは多くの方に知ってもらって、意見をもらうことが大事であると思いますし、まさに学校の関係者、保護者の方々などに見ていただいて、さらには意見をもらうことが良いとと思うのですけれども、例えば、学校などで閲覧する、知っていただくことはいいと思うのですけれども、いかがでしょうか。","respondent":"舩木庶務課長","answer":"今のところ各学校は予定してございませんが、資料に記載のとおり、本庁舎、教育委員会に加え、地域センターもありますので、各地域の核となるようなところで、あえて、紙を手に取ってご覧いただきたいということで、こういった形で進めさせていただければと考えております。","voiceIndex":32,"id":"exchange-010"},{"speaker":"山本副委員長","kind":"意見","question":"現状では、既に考えているということで理解いたしました。私も区内小・中学校に通う子どもがおりまして、感じることとしては、学校にはＰＴＡやそれ以外の保護者の方が出入りされる機会も結構あります。学校の入り口の受付などに置いていただくとそういった保護者の方の目にとまる機会にもなるのかなというところで、効果的に見ていただけるのかなと思いますので、御検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"私からも１点質問と、感想も述べさせていただきたいと思います。１点伺いたいのが、柱２に「誰一人取り残さないきめ細やかな教育」とあるのですけれども、特に私自身に不登校のご相談が多いため、不登校対策の方針に関しては、どの部分に該当するのかなと思いながら拝見いたしましたが、幾つか横断するかもしれないので、私には発見できませんでした。","respondent":"丸谷教育総合支援センター長","answer":"こちらにつきましては、４６ページにあります、方針７の「ダイバーシティ＆インクルージョンに根差した教育」という方針の中で不登校支援の１つの例として「メタバースを活用した学習支援」をあげています。","voiceIndex":36,"id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"３４ページの方針７の具体例が、今、教育総合支援センター長がおっしゃってくださった４６ページに記載されているのかなと思います。要望でもあるのですが、特に誰一人取り残されないという意味においては、ぜひオンライン学習の教育ＤＸの進化を計画に反映させていただきたいなと期待をしておりますので、どうぞよろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問・要望","question":"先ほど、子どもの声を聞いてきたというお話があったのですけれども、何人ぐらいのお子さんの声を聞いたのかというところを教えていただきたいと思います。以前出ていたら申し訳ないのですけれども、空欄ではあるのですが、５２ページの「子どもワークショップからの意見」というところで、このワークショップはいつ開催するのかというところを教えていただければと思います。","respondent":"舩木庶務課長、柏木学務課長","answer":"既に、９月の３日、５日、６日の３日間をかけまして、それぞれ小学校、中学校、義務教育学校１校ずつ選定をしまして、１回当たりおおむね２０名程度、多少前後いたしますけれども、４名程度のグループごとに分かれまして。今後、予算編成の中で、様々議論しながら整理をしていきたいと考えています。","voiceIndex":40,"id":"exchange-014"},{"speaker":"せらく委員","kind":"質問","question":"無償化の部分では、こちらの計画の中には、文言として教材費と給食費が入っているところですけれども、今後、ほかの部分も追加される可能性があると認識してよろしいでしょうか。","respondent":"柏木学務課長","answer":"今、これをやるというものはないので、お答えできないところですけれども、先ほどの答弁の繰り返しになりますけれども、今後、予算編成の中で様々議論しながら整理をしていきたいと考えています。","voiceIndex":43,"id":"exchange-015"}]},{"id":"topic-02","title":"令和５年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和５年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"田中委員","kind":"確認","question":"何点かお伺いいたします。全体を通じてなのですけれども、「当てはまる」と「どちらかと言うと当てはまる」というものを合算して、総じて９０％以上で、個別には違うのかもしれないですが、いい傾向になっているかと思うのです。併せてお伺いしますが、特に保護者アンケートの６番の「現在通っている学校に満足している」というところで、「満足」が全体で９２.５％とあります。そこを確認したいと思います。","respondent":"中谷指導課長","answer":"こちらに関する分析としましては、一人ひとりの児童・生徒へのきめ細かいアプローチというのは、様々な教育活動で実施しているところで、一定の成果はある一方で、一部のお子さんに対する学習支援、もしくは不登校の対策も含めて、個別なアプローチを。","voiceIndex":50,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"いい評価は、もちろん心強く、これまでの施策が良かったということで自信につなげていただきたい一方で、また、さらなるよりよい教育につなげるヒントが隠されている可能性もありますので、そうではないという意見は意見でしっかり捉えていただいて、そこはぜひ受け止めていただきたいと思います。この分析結果を見て、どのように受け止めていらっしゃるのか。","respondent":"中谷指導課長","answer":"令和５年度から、全校で「品川コミュニティ・スクールＤＡＹ」という行事を実施させていただいておりまして、この取組は、通常、校区教育協働委員会で行っております、大人同士の議論に加えて、その学校のお子さんにもご参加いただいて。","voiceIndex":52,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"このような傾向で、経年的な評価も、今、お話いただいたとおりだと思っていますので、そこも含めて、しっかり保護者の方や児童・生徒の方の声を教育の改善に活かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"西村委員","kind":"質問・要望","question":"４番の将来なりたい職業ややりたいことのところで、「どちらかと言えば当てはまらない」、「当てはまらない」と書いた児童・生徒のやる気につながる取組につなげたいなと思いますので、何かお考えがあれば、お聞かせいただきたいなと思います。今、お話にもありましたけれども、５番のボランティア活動について、日常の何を指すのかピンと来なかった児童・生徒もいるのではないかなと思います。","respondent":"中谷指導課長","answer":"むしろやったほうがよいという受け止めをしております。そのような意味でも、校長会にもこういった内容を働きかけて、今、取り組める「しながわドリームジョブ」などの取組にもぜひ希望を挙げていただきたいという投げかけをしてまいりたいと考えています。","voiceIndex":56,"id":"exchange-019"},{"speaker":"西村委員","kind":"意見","question":"「しながわドリームジョブ」、私、大変大好きな取組で、すばらしい取組だと思っているのですが、本当に今おっしゃっていただいたとおりだと思っておりまして、悩み始める時期、心の惑いみたいなものもこの中に表れているのかなと思いました。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお願いします。同じように、児童・生徒に対してどのようにフィードバックされるのかということをお尋ねします。児童センターのイベントをお手伝いしたとか、地区委員会のイベントや、中学生が小学校の運動会のお手伝いをしたなどということがたくさんあると思うので、そういうボランティアの事例がリスト化されて、学校に提示されているのかというところをお尋ねします。","respondent":"中谷指導課長","answer":"お子さんの多様性のところに関する設問ですけれども、特別支援学級がある学校の数値と、そうでない学校については、今、実際、全てを見ているわけではないのですが、一般的には特別支援学級がある学校のほうが。","voiceIndex":60,"id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"このようなことから、今まで分からなかったことが分かっていくので、ぜひ次の学習活動に活用していただきたいと思います。ボランティアについては、学校地域コーディネーターの方々のネットワークの中で、うちの学校はこのようなことをやっているよということで、かなりコーディネーターの方同士のネットワークですごく緊密にやりとりが行われていると伺っているので、そこでもお話が出ていると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"},{"speaker":"山本副委員長","kind":"質問","question":"私からも２点伺わせていただきます。この計画の推進をしていくに当たって、次年度以降、こういった方針に対しての児童・生徒や保護者のアンケートを進めていくことになると、来年度以降は変わった形にしていく必要があるのかなと思ったのですけれども、そこら辺をどのようにお考えかということをお聞かせください。","respondent":"中谷指導課長、舩木庶務課長","answer":"最初にＩＣＴのご質問にお答えします。設問７の回答結果ですけれども、やはりＩＣＴの活用というのは、校種を問わず、年々進んでいるかなと思っています。それぞれ計画素案を踏まえました様々な内容に関しましては、まさにこの計画がこれからしっかりと策定できた段階で、児童、保護者の方、いろいろな地域の方などに、しっかりと浸透して、学校教育や。","voiceIndex":64,"id":"exchange-023"},{"speaker":"山本副委員長","kind":"質問・要望","question":"設問７のデータの読み取りですけれども、理解いたしました。そして、企業とコラボレーションして体験していくといったご説明はとてもすばらしいと思いますので、ぜひともそのようなことをして進めていただきたいと考えています。併せて、どう効果検証していくかというところもすごく大事だと思いますので、ぜひ在り方のほうも検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-024"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"今回、いじめの重大事態の分類が１号、２号、どちらも当てはまるということなのですけれども、これまで１号か２号どちらかということだったので、どちらも当てはまるということは結構重大な内容だったのかなと思うのですけれども、その辺りをお聞かせいただけますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今回、１号および２号という形で、現時点で詳細をこの場でお伝えすることはなかなかできないのですけれども、１号は生命、心身、財産に重大な被害が生じた疑いがある。２号は相当の期間、学校を欠席することを余儀なくされている疑い。","voiceIndex":73,"id":"exchange-025"}]},{"id":"topic-04","title":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。これは、いわゆる運営側の努力もあるのでしょうけれども、コロナ等もありましたが、何かそのほかに分析されていることがあるのかどうかということが１つです。６ページを見ると、「有資格者配置率は６１％と高い水準を維持している」とありますが、これは何と比べて高い水準を維持しているのか、何と比較しているのかというところも少し教えていただければと思います。","respondent":"河内品川図書館長","answer":"資格要件ですが、そもそも任用する際に、そういった経験、あるいは免許の有無によって採用を決定するとともに、こういったご経験がない方に関しましては、内部研修、あるいは外部研修の補助などを行い、様々な指定管理者の工夫の中で。","voiceIndex":84,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"意見","question":"全国でいわゆる本屋の数が激減してきているということ、本離れということでよく報道されますけれども、そういった中で微減というか、マイナス２％、３％というのは非常に健闘されているのかなというのが正直な感想です。そこについては、区側もしっかりと支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"提案","question":"図書館については以上で、もう一点だけ、まとめて質問いたします。現状、品川区だけではなく、全国の自治体がやっています。実は、今年、行政視察先の候補地として私が提案した徳島市では、ファミリー・サポート事業で、いわゆる依頼会員はワンコイン、５００円で利用できるけれども、区で助成して提供会員の報酬を９００円に高めるといった努力というか、そういった改善策をとっていました。","respondent":"染谷子ども家庭支援センター長","answer":"それに加えまして、養成講座の受講料についても、現在、具体的には１０月１日から１,５００円が１,６００円に変わるというところでご本人の負担が発生している部分を、こちらで補えないかといったところや。","voiceIndex":88,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"今日は指定管理者のモニタリングというところなので、区の事業そのものなのですけれども、区の取組とは少し外れてしまうところではあるのですけれども、今、真剣に、真摯に取り組んでいただいていることが確認できましたので、できれば来年度から、今おっしゃられた検討・研究されていることを１つでも実現していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-029"},{"speaker":"西村委員","kind":"質問","question":"幾つか伺います。図書館なのですけれども、ゆたか図書館、エコルとごしに出前図書館として環境図書を置いていただいているのは私も拝見したことがあります。あくつ委員もおっしゃっていましたが、本当に地域に寄り添っていただいて、区民に寄り添っていただいている取組が様々ありますので、指定管理者の中で取り組んでいることがあれば、伺いたいというのが１点です。","respondent":"河内品川図書館長、染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"例えば、水族館など、様々な施設がありますが、そういった特徴に合わせまして、選書本を特集で用意いたしましたり、いろいろな地域の方との連携や。子育て短期支援事業における年齢拡大に関してお答えいたします。何か子育てのところで気になる点等があれば、今までもそうですが、子ども家庭センター、または児童相談所とも連携しながら、一緒に考えてまいります。","voiceIndex":92,"id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"不登校の子どもの居場所としての広がりもあると思いますので、そこは学校と連携していただいていると伺っているのですけれども、あまり知られていないなという実感がありますので、品川区の図書館は本当に居心地がいいですから、ぜひ来てもいいよと言ってあげられるような周知と、不登校ポータルサイトへの記載などもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。そういう観点で、今後の図書館とまちづくりとの関わりをどのような形で役割を果たしていくかというところを少し伺いたいです。やはり図書館が主体となって、部署を超えて連携していくというのは、いろいろあるかと思いますけれども、図書館の持っている本や役割、あるいはいろいろな特集をできる指定管理者のパワーなどもあると思うので、その辺を少しお願いします。","respondent":"河内品川図書館長","answer":"そのほかの人の流れについて、今後、魅力的な図書館運営として気をつけていかなければいけないのは、障害者のバリアフリーなどの対応、例えば、ヤングケアラーの方もそうですし、日本語を母語としない方もそうですが。","voiceIndex":98,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後も、ぜひまちづくりの核として、より一層図書館を活用していただきたいと思います。ぷりすくーるのほうなのですけれども、これは確認で、公私連携で幼保連携、認定こども園化の流れがあったと思うのですが、それと指定管理者との話合いというか、準備というか、もしその辺が分かれば、お願いします。","respondent":"芝野保育入園調整課長","answer":"ぷりすくーる西五反田の認定こども園化に向けたお問い合わせ、ご質問ですが、常に指定管理者とは連携しながら、話しあいのほうは進めておりまして、あくまでもスケジュール感的なものですが。","voiceIndex":100,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"少し先の話ですけれども、ぜひ円滑に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"３グループあるうちのＡグループとＣグループが同一の指定管理者で運営されておりますが、契約内容に関わるのかもしれませんけれども、Ａグループの成果、Ｃグループの成果を反対側のところに活かすことは可能なのかどうかということと、同様の視点で、Ｂグループはほかの事業者ですが、それぞれ企業のノウハウですので、なかなか開示しづらい部分もあるのかもしれませんが、１つの成果として。","respondent":"河内品川図書館長","answer":"各館におきましては、館長が個別に任命されておりまして、館長会議では、その館の特性や地域の課題に沿いまして、他の図書館へ共有するようなところがあります。その中で、指定管理者ですので、例えば、館の運営、選書、トラブル対応、いろいろな強みがあります。","voiceIndex":104,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう中で、ここにもあるように、開園されて２０年、施設としては約３０年ぐらいですか。何回か私も言っていますので、この程度の対応で大丈夫そうではありますけれども、とはいえ、何があるか分からないという観点も含めて、安全管理、確保についての今現在と、将来的な建て替えも含めて、安全確保の視点での区の責任についての考えをお聞かせいただきたいと思います。","respondent":"芝野保育入園調整課長","answer":"建て替えの考え方ですが、まだ施設が２０年ですので、まだそこまでの計画は出ておりませんが、老朽度に応じて、今後、検討していかなければいけない課題であるということは認識しております。","voiceIndex":106,"id":"exchange-036"}]},{"id":"topic-05","title":"法改正に伴う児童扶養手当の所得限度額の引き上げ等","agenda":"法改正に伴う児童扶養手当の所得限度額の引き上げ等","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今回の限度額の引き上げに伴いまして、対象人数が増えてくると思いますが、どれぐらい増えるのか。今までと比較しまして、トータルでどれぐらいの支給額が増えるのか、お聞かせいただきたいと思います。","respondent":"飛田子育て応援課長","answer":"今のところ、試算しますと、約３４０人ほど増えるのではないかと考えております。予算としまして、令和６年度分の増額として、現在６,５８５万円を想定しています。","voiceIndex":120,"id":"exchange-037"}]},{"id":"topic-06","title":"順番を入れ替えて、予定表の３、その他","agenda":"順番を入れ替えて、予定表の３、その他","exchanges":[{"speaker":"西村委員","kind":"質問","question":"ここまでお調べいただいて、本当にありがとうあります。大変感動しておりまして、一番最後のところは、この施設に直接見に行かせていただくのだろうなということが分かるのですけれども、大和郡山市などは、どこでお話を伺うのか。役所の中でお話しいただくだけなのか、「ＡＳＵ」に行くのかということがもし分かれば、教えていただけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6825#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":52100,"voices":142}},{"id":"r06-20240925-5","meetingId":"r06-cm09","date":"2024年9月25日","dateIso":"2024-09-25","committee":"総務委員会","time":"午前１０時００分～午前１１時１９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に各所管委員会における審査結果","agenda":"説明に入る前に各所管委員会における審査結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"何点か伺いたいんですけれども、教育総務費の特別支援学校補助教材費保護者負担軽減事業についてですけれども、私たちも総務委員会等で求めてきたのですが、実施されてよかったなと思うのですけれども、なぜ９月の補正で予算を組んだというのが分かれば教えていただきたいのと、民生費で１５ページのとうきょうすくわくプログラムについてですけれども。","respondent":"加島財政課長","answer":"それから補助の期間が６年間ということで、６年経過した後、どうなっていくかというところなのですけれども、今、６年経過後の補助スキームについては東京都から示されているところではございませんけれども、この補助期間の６年間を使って園のほうで備品を購入したりですとか。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"当初予算でも執行していて拡大している、例えば、１５ページの高齢者の難聴サポート用イヤホンです。それで、今回拡大という形になっているのですけれども、今回の予算の中で当初予算にはなかったのだけれども、すくわくはいいですけれども、品川区がやろうとしていたけれども、なかなかできなくて、今回、この９月の補正で入れ込んだというのはあるのかどうかをまず確認したいと思います。","respondent":"加島財政課長","answer":"介護支援専門員、ケアマネジャー法定研修の受講料ですとか、産業経済費では省エネルギー対策、令和５年度補正でも入れましたけれども、当初予算ではございませんでしたが、こちらを新たに今回の補正で入れさせていただいているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"何かしらの指針というのがないと、平等にと言っても、これは東京都の事業なのです。品川区で考えたものではないのです。少し中に入り込んでしまうのかもしれないのですけれども、これは企画課なのかな、どうなのですか。ちょっとその考え方はどうなのでしょうか。これはどういう考えで今やろうとしているのでしょうか。","respondent":"加島財政課長","answer":"今回、年度途中ではありますけれども、東京都のほうでたまたま区で実施を目指していた方向と合致する補助金がございましたので、区立園全園、それから希望する私立園のほうでこの補助金を使ってこの教育を実践していきたいという考えを持った次第です。","voiceIndex":10,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"なので、もう既にやっているよねというところも往々にしてあるのではないかな。だけれども、品川区はもう既にやっている部分があるので、その考え方というのは先ほど現場の保育士たちの意見はどうなのだという話もありましたけれども、そこは今までやってきたことの整合性はどういうふうにされているのかなと思うのですけれども、いかがですか。","respondent":"加島財政課長","answer":"子どもたちの情操教育、感性を豊かにというのが今回の探究心を育てるですとか、好奇心を育てるというところのベースとしてはあるかと思うのですけれども、区のほうで今回、何といいますか。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"あまり長く続くと、どんどん中に入っていってしまうので、ちょっとやり過ぎてしまっている部分があるので、ただ考え方をお聞きしたいと思います。どういうタイミングで今までやってきたこと、それから実績もあります。義務教育学校になったではないですか。もっと品川区発信でいろいろやれるのではないの、やってきたよねというのが非常にあるのですけれども、その考え方をお聞きしたいと思います。","respondent":"加島財政課長","answer":"ただ、この間、物価高騰ですとか、生活のところも歳出抑制ですとかがある中で、今、では区として何をしていくべきか、また、義務教育として区として向き合ったときにどの視点かというのを考えたときに、少しその方向性が、例えば、保護者の費用負担軽減であったり。","voiceIndex":14,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"職員の方々の思いというのは本当に私は実感しております。これからもそういう思いでやっていただきたいなと思うのですけれども、ばらまきが多すぎるのです。いや、別にいいです。ばらまきをやったっていいのです。今後、品川区はどういう考え方でやろうとしているのか、企画という観点で教えていただきたいなと思っています。","respondent":"久保田企画経営部長","answer":"一方で、第二子の保育料の無償化といったところも取り組んでまいりましたし、高齢者の部門では難聴対策でも所得制限をなくすとか、そういったところでできるだけ多くの方が取り残されることのないように所得制限を撤廃するなど、そういった取組を進めてまいりまして。","voiceIndex":16,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"ばらまきというのは私の感覚なのです。子どもたちをどうしていくのだというのがあったと思うのです。だけれども、それ以上に必要なのは、これからどうするの。それは大切にしてほしいなという思いがありますので、この補助金の使い方にしても根拠をちゃんと示して、こういう根拠の上で柱の下でこの補助金は使うのですというのをぜひ今後、説明の中には加えていただきたいなと思います。","respondent":"久保田企画経営部長","answer":"今回の補正予算につきましても、子どもたちのいろいろな探究心などを伸ばしていくといったところ、これまで取り組んできたものの中で東京都からそのような補助金が創設されたということを聞きましたので、そういった補助金も活用しながら進めていきたいです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"「あれ？それと、１７ページの中小企業活性化事業費ですが、先ほど冷暖房という話がありました。補正をこれから執行するのだったら、時期的に、地域産業振興ということで活性化事業としてやるならば、もっと前に、５月とか６月にやるべき話だと思うのですけれども、何でここで出てきたのかなというのを教えてください。予備費でも何でも執行をどんどんするべきではないのですか。その３点だけ教えてください。","respondent":"加島財政課長","answer":"１点目の省エネルギー対策・業務改善設備更新助成金についてですけれども、今回９月補正となった理由について、こちらは国のほうで８月から１０月まで電気料抑制策が取られていましたけれども、今のところ、１１月からはその抑制策がなくなる予定です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"長く使えたというよりは、決まり事で、だったら、ほかの工事になる可能性があるなら、入札には参加してほしくないし、入札したからには、私は、社会通念上、しっかりその納期には押さえるのだと。区としてもしっかり予定を組んで、各事業を進めているのですから、私は今回のは問題があるのかなと思います。意見だけ言わせていただきます。","respondent":"加島財政課長","answer":"私のほうで鈴ヶ森小学校について説明不足の点があったので、補足させてください。鈴ヶ森小学校の仮設校舎賃貸借に関する件は建設も含んでいる契約なのですけれども、入札が不調になりましたので、入札して契約が締結された後、契約期間の延長の交渉があったわけではございません。","voiceIndex":23,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"そうするとまた言わなければいけないのですけれども、６か月、結局、不調で延びた。過去にもありますけれども、そういうことがあるというのは一つ大きな、契約の時点で問題点として指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回、いろいろ継続実施等を求めてきた省エネルギー対策の拡大とか復活、学校補助教材費の無償化の特別支援学校への拡大など、区民にとって大事なことが含まれておりますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"賛成としますが、先ほど企画経営部長からのお答えもいただいて、お考えもお聞きしました。やはり品川区独自のというところはぜひお願いしたいなと思います。対外的に独自の発信力がかなり落ちているのではないかなと考えていますので、そこは職員の方々、思い出してと私は思いますけれども、今までやってきたのでできるわけですからということで期待を込めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"西本委員","kind":"確認","question":"内容は大変よかったと思うのですけれども、東京都に出した意見書、国にもそうですけれども、何かフィードバックってあったのですか。今までそういうフィードバックをもらっていなかったような気がするのですけれども、そういう要求はできないのですか。出しっぱなしというのも何か、どうなのですか。そういう要求はできないのですか。ちょっと確認してもらっていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-03","title":"荏原文化センター大ホール照明更新工事請負契約","agenda":"荏原文化センター大ホール照明更新工事請負契約","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今回、舞台照明の設備の改修工事ということで、ピンスポットライトが従来のハロゲンランプだったのがＬＥＤ化するというところでは、これは要はＬＥＤ化がどんどん進んでいる中で、荏原文化センターの大ホールの照明もハロゲンだというのは分かっていたと思うのですけれども、このタイミングになるというのは順次ということで、今なのでしょうか。そのタイミングのところをお聞きしたいのですけれども。","respondent":"長尾施設整備課長","answer":"こちらの荏原文化センターにつきましては、通常の蛍光灯などの照明器具とは違いまして、特殊な舞台の演出の照明器具になっておりまして、前回設置したものから経過年数としておおむね１０年程度たっておりますので、ちょうど更新時期が来ておりましたので。","voiceIndex":45,"id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問","question":"何年かで工事をするより、いいのではないですかみたいなお話も伺ったことがあって、今回のとは少しずれてしまいますけれども、例えば、そうやって壊れたものは工事するのも当然のことですけれども、大きな部分で言うと、この荏原文化センターもまた建て替えると、あそこら辺だと同じものは建たないという危惧もありますけれども、そういう方向性とか考えというか、そういうものはどうなのですか。","respondent":"長尾施設整備課長","answer":"荏原文化センターにおきましては、公共施設等総合計画の中で改築をする時期としましては、今からですと、３０年、４０年後ということで、まだ長く使っていく計画にしております。","voiceIndex":48,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"私もまつざわ委員がおっしゃっていたことを伺おうと思っていたのですけれども、古いなと思っているのです。あそこは図書館も入っていますね。なので、古きよき時代の産物もあるかもしれないのですけれども、もう少し近代的な形に考えてもいいのではないかなと思うのですが、長寿命化と決まっていると言いつつも、変更はあり得るのか、どうなのでしょうか。前向きに考えてほしいなと思います。","respondent":"長尾施設整備課長","answer":"建て替えを検討してはいいのではないかというお話ですけれども、私の立場だけでは方向性を変えるとか決めるというわけには行きませんので、今後の活用については引き続き所管課ともきちんと協議・調整をしながら進めていきたいと考えております。","voiceIndex":50,"id":"exchange-016"},{"speaker":"西本委員","kind":"意見","question":"この文化センターの在り方も考えたほうがいいのではないかな。文化センターとは何という。なので、そうすると、委託というやり方もいいのかどうかも含めて、文化センターの在り方については今後、議論していただいたほうがいいのではないか、品川区にとってどうなのだろうか。でも、企画経営部長も副区長もいらっしゃいますので、全体的に考えるべきことなのかなと思いますが、答えられる範囲でお願いします。","respondent":"長尾施設整備課長","answer":"文化センター含め、こういった文化施設につきましては、所管課のほうで文化芸術・スポーツ振興ビジョンであるとか、文化スポーツ施設の長寿命化計画というものを策定した上で、施設についても在り方というのを整理して、今順次計画的に長寿命化であるとか、大規模改修であるとか。","voiceIndex":52,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"この長寿命化は当たり前なのです。このご時世のことですから、長寿命化という話でいろいろと考えていってというなるべく長く使おうよという動きは分からないではないのです。それを考えると、やはり長寿命化も含める、そこも必要なのだけれども、目的もどんどん変わってきている中で、大胆に方向性を見直してもいいのではないかなと思いますので、ぜひ今後、議論の中に入れていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"昨日も申し上げましたけれども、今回も辞退、辞退ということで、これは私の意見として、配置予定技術者の配置が困難になったためというので、もう辞退ではなくて、もう入札に入るのをやめていただきたいなと思うのです。それに共同企業体というのは必要になるのですか。１社で十分賄えるように思うのですが、マスミ電設は確かに電気工事の専門だと思うのですけれども、それだけ理由を教えてください。","respondent":"佐藤経理課長","answer":"共同企業体に関してということだと思いますが、こちらに関しては施工能力もそうですし、あとは区内の事業者の育成というところもありますし、区内事業者への受注機会の確保というところもありまして、一定の基準に沿って設定しているというものです。","voiceIndex":56,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけで。育てるということがありましたけれども、三英建設とマスミ電設、片一方は電気で片一方は建築、構造のほうをやっているので、それが三英建設が電気事業、三英は電業は電業で持っているはずです。だから、それが不思議な組合わせだと私は思いますので、今後、何か対応を私は考えていただきたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-020"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"お忙しい中、ありがとうあります。私はもっと数がいっぱいあって、多くの事業者が大変だというようなご意見がいっぱい来ているのかなと想像したのですけれども、ちょっと違っていました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"すみません。毎回毎回聞かせていただいておりますが、「秀」の件はどこまで動いていますか。それだけ確認をさせてください。","respondent":"勝亦総務課長","answer":"国際友好協会の関係ですので、現在、国際友好協会と持ち主の方との間で賃貸借に向けて協議、それからその受入れのための準備をしているという状況だと聞いております。","voiceIndex":68,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"前回の委員会のときと同じご答弁なのですけれども、進展はないという、継続してお話合いが進んでいますという段階なのですか。","respondent":"勝亦総務課長","answer":"契約が必要になってまいりますので、契約の準備をしているという状況でございまして、継続的に協議、準備をしているです。","voiceIndex":70,"id":"exchange-023"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"こしば委員長","kind":"提案","question":"長野市です。ガイドラインや規程については３ページから２４ページまで掲載していますので、後ほどご確認願います。次に、視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言いただきたいのですが、先日もお伝えをしましたとおり、各視察先より質問事項の事前送付の依頼があります。現時点において視察先で特に質問や確認したい事項、ご要望等がございましたら、ご発言を願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-024"},{"speaker":"松本委員","kind":"確認","question":"長野市で、都市ブランディングということかと思うのですけれども、聞きたいこととしては、都市ブランディングは成果の確認が物すごく難しいと思うのですけれども、そこでどういう指標を設定されて、どういうふうに測っているのかというところです。もう数年やられていると思うのですけれども、この成果についてどういうふうに評価されているのかというところはお伺いしたいかなと思います。品川区は「わ！","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"１０月４日までに意見をまとめて出しますけれども、都市ブランディングという言葉、それからシティプロモーションというのがあって、シティプロモーションとの違いというのは意外と分かっているようで分かっていないのです。長野市が取り組む前、シティプロモーションをやっていたのかな、どうなのかなという。品川区もシティプロモーションをやっていて、「わ！取り組んでいればの話です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"ちょっとずれるかもしれないのですけれども、議会報告会のテーマがＳＤＧｓなのですね。なので、それを意識して勉強したいなという思いがあります。だから、１０月の末で実際、１２月ですね。だから、ＳＤＧｓというとちょっと絞りづらくて。なかなか絞り切れない部分がある。載せていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6833#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":24235,"voices":85}},{"id":"r06-20240926-14","meetingId":"r06-cm09","date":"2024年9月26日","dateIso":"2024-09-26","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"私どもも町会・自治会等と触れ合う機会は多いのですけれども、そう触れ合っていない区民の方も非常に多いという中で、地域社会ということにどういう関心を持たれてこのテーマを選ばれたのかという根拠になる部分、根拠というのは固いものではないですけれども、どうしてこのテーマを選ばれたのか、区民の関心がどこにあったのか、そもそも論で教えてください。","respondent":"吉岡政策推進担当課長","answer":"こういったことを契機に、どういった支援を行っていくかというところで、祭りだけではなくて、地域の活動に皆さんにご参加いただけるのかということを含めまして、これは祭りだけですと非常に狭い分野になってしまいますので、広く捉えて地域社会というところで、今回。","voiceIndex":7,"id":"exchange-001","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。祭りというのは確かに代表的な地域のイベントであって、いわゆる神社の祭礼から、区民まつりとか、また最近では宿場まつり等もこれから開催されますけれども、そういったイベントとしての祭礼、祭りということは分かりました。先ほど、ご説明の中であった商店街というところへの区民の関心、アンケート等で何か読み取れるところがあったのか、そこについてもう一度教えてください。","respondent":"吉岡政策推進担当課長","answer":"しかしながら、町会・自治会の活動の中で、地域でいわゆるステークホルダーとしてご活躍していただいている団体の連携を促していくことが重要というところもあります。","voiceIndex":9,"id":"exchange-002","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"９月１０日ですから、直近でまだ開かれたばかりで、当然まだまとめ作業はないと思うのですけれども、またこれから決算特別委員会等でそれは披露されるのかなとも思うのですが、最後に少し伺いたい。有識者とか、また地域の区民の委員の方から、どういった意見が出たのか、代表的なものを最後に教えてください。","respondent":"吉岡政策推進担当課長","answer":"政策評価委員会の中で、どういった具体的なご意見が出ていたかというところなのですけれども、１つご紹介しますと、公募区民の方ですとか、今回、大学生の方に参加いただいているのですけれども、地域、町会や自治会が何をしているか分からない。","voiceIndex":11,"id":"exchange-003"},{"speaker":"筒井委員","kind":"質問","question":"政策評価について、私からも伺いますけれど、今回、令和６年度は評価対象分野が地域社会ということになりましたけれど、令和５年度は防災強靱化、そして環境ということだったと思います。この評価対象分野は、今後どういう工程で決められているのか。","respondent":"吉岡政策推進担当課長","answer":"中長期的に、こういった分野を回していこうという考えは、検討中でございまして、具体的なことは申し上げられないのですけれども、１つ考え方として示させていただいたところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問","question":"私から２点、質問します。１点目が、それぞれ事業の目的に対して、事業の概要でご説明をいただいておりますけれども、この概要、事業として取り組んでいるものが適切かどうかということ、それから、定量的な目標設定が妥当かどうかの判断は、誰がどのようにされているのでしょうかというところがまず１つです。","respondent":"吉岡政策推進担当課長","answer":"続きまして、こちらの事務事業評価に外部委員を入れるのかというお話がございました。事務事業評価シート、先ほど申し上げたとおり、６６９事業あります。これを１から事業を説明して評価をしていただくことは現実的ではないというふうに考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。お考えについて理解いたしました。効果をさらに高めるために、さらに改善を進めてほしいというふうに思っております。それから、前回の議題となった行財政改革特別委員会でも申し上げましたが、区民の皆様へも分かりやすく説明するための工夫も検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、２回目をつくり上げるに当たりましては、昨年の評価シートをどう生かして今回つくられたのか、横引きで同じということはないと思いますので、それぞれまた更新をしていくという観点から、１つ１つまた精査をしてつくり上げてきてくださったと思うのですけれども、１年目につくられたこと、そして、今回、２回目ということで。","respondent":"吉岡政策推進担当課長","answer":"当然、記載については一からチェックをする、横引きではないのですけれども、昨年度、一定、記載の方法ですとか、評価の仕方、そういった部分については、説明会を通しながら、また、修正のいわゆるキャッチボール、そういったものもしながら。","voiceIndex":18,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、先ほども少しありましたけれども、この間、３回、政策評価委員会が行われてきたということで、町会が何をしているか分からないということが主な意見だったということですけれども、ほかに何か議論されたことがあれば、ほかにも商店街やＮＰＯですか、そういったところも対象になっているということですので、どういった議論がされたのかというところを伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"最後に、先ほど、事務事業評価の中で福祉を切り捨てないというか、そういったお話があったかと思うのですけれども、こちらは事務事業評価については、事業について、しっかりと見直しを行っていながら、より効果的な手法。","voiceIndex":21,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりそういった事業は、寝たきりの方、そしてご家族の方も含めて、大変助かる事業だと思いますので、そうした福祉の切り捨てがないように、これは改めて強く求めておきたいと思いますので、さらにご答弁があれば伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"必要な福祉施策につきましても、今年度も当初予算から、あるいは補正のところでもいろいろ対応させていただいてありますので、来年度以降も、こういった事務事業評価を通して、そういったものを確保しながら実施していきたいというふうに考えてあります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"せらく委員","kind":"確認","question":"政策評価委員会について少しお聞きしたいと思います。メンバーに大学生が２人いらっしゃったということで、大人ではなく学生を入れたというところの思いをお聞かせいただければと思います。もう１点、政策評価委員の公募を行っていらっしゃることをホームページで確認したのですけれども、任期が１年というふうに書いてあります。お願いします。","respondent":"吉岡政策推進担当課長","answer":"なぜ大学生を入れているのかというところになりますけれども、公募区民という形で募集をいたしますと、なかなか若い世代の方からは手が挙がらないというところもありますので、今後の品川区を背負っていく。","voiceIndex":25,"id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"今、２人の委員から、評価委員会の委員について確認がありましたので、１点、確認します。ここの団体の方が増えることは問題ないと思いますが、公募区民の方が３名から２名になっているというところで、より多くの声を聞いていただくには、公募区民の方の人数は必要かなと思っているのですが、今回減った理由だけ教えていただけますか。","respondent":"吉岡政策推進担当課長","answer":"ただ、次年度以降、実施するときにおきましても、今年度こうやって人数の構成を変えたけれども、どうだったのかというような振り返りをさせていただいて、次年度、どういったメンバーでやっていくのかというところは改めて検討していきたいというふうに考えてあります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"様々テーマによって構成を検討された結果というふうに受け止めましたが、やはりより多くの区民の声は、本当に現場といいますか、生活に根差したお声が聞けるかと思いますので、１人、２人の増員というところも、時間的な制約もあるかと思いますが、より多くの声を直に聞けるというところでは、公募区民の方もしっかりと人数は確保していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"つる委員","kind":"確認","question":"事務事業をスタートする前、総務委員会でいろいろ審議させていただいたときの質疑を改めて確認して、いろいろ申し上げたなとかということも思い出しながらなのですけれども、昨年度の決算特別委員会のときに事務事業評価シートを提示いただいて、令和４年度の事務事業評価を拝見させていただいてというところでの決算特別委員会ですけれども、この目的のところからすると、評価を精いっぱいやっていただいて。","respondent":"吉岡政策推進担当課長","answer":"この事務事業評価、本格実施は今年度２年目です。１年目に行ったところで、全庁的に、よりスクラップ・アンド・ビルドの考え方ですとか、あとは、事務事業の効果の判定の仕方ですとか、把握の仕方、こういったものが全庁的に根づいてきたのかなです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"各所管に、当然それは、この後ある人材育成ではないですが、各部署の成長というか、区民のサービスの向上という観点で、どう事業の展開を考えていくかという力をつけていくということが必要なのですけれども、やはりこのベースに基づいた考え方というか、施策展開、職員提案制度などで今年度もいろいろな事業の提案が出てきているとは思うのですけれども、そういったことも含めて。","respondent":"吉岡政策推進担当課長","answer":"いわゆる事務事業評価シートの財務情報の部分ですけれども、今までも研修を通して、あるいは、事務事業評価においての説明会を通して、こういった部分についてご説明を、庁内で共有を図ってきたところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"分かりました。そこは期待をしていきたいと。最後に確認で、例えば今、それぞれ６６９事業、よい意味で細部にわたって掘り下げて、１つの事業をぐっと見ていくわけですけれども、その事業だけが単独で何か１つ課題に対して事業を行っているわけではないですよね。その事業と、ほかの事業、それこそ所管をどう超えて関係する。","respondent":"吉岡政策推進担当課長","answer":"一方で、ここで出したものをひもづけていく、施策、政策として、実施計画の改定も行っておりますけれども、そういった大きな施策、そういった束ねた中でどういった効果を発揮しているのかというところは。","voiceIndex":34,"id":"exchange-015","title":"町会・自治会支援"},{"speaker":"つる委員","kind":"質問・要望","question":"今言っていただいた事業、施策、政策と１つ大きなカテゴリーがあるわけです。そうすると、この政策評価などというものは、先ほど質疑が若干あったけれども、大きいくくりでの評価となっていますね。なので、先ほどご答弁いただいたとおりなのですが、引き続き、よりよいものにしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"少し感想も含めてなのですけれども、まさに今、つる委員がおっしゃったみたいに、事務事業評価の評価でしたり、成果だったり、これからまさに考えていくようなシーンになっていくのだろうなと思っているのですけれども、６６９もの事業の財務諸表でしたり、そういったものを読み込んでいただいて、区民、有識者による評価委員の方にとって、適切な評価を行っていただくということが。","respondent":"吉岡政策推進担当課長","answer":"やはり先ほどもお話がありましたけれども、分かりやすい資料、知っていただくための機会、こういったものは設けていく必要があるのだろうというふうに捉えているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"筒井委員","kind":"提案","question":"先ほども新妻委員からもご提案がありましたけれど、やはり、この地域社会については、課長からもご答弁あったとおり、町会の活動が何をやっているか分からないとかという区民のお声があるということなので、よりリアルな区民の声を多く拾っていかないといけないかなと考えていますので、ぜひ、委員会の人数を増やすこともよいですし、適宜アンケートをとったりして、より多くの区民の声を拾っていって、政策。","respondent":"吉岡政策推進担当課長","answer":"この「地域社会」も、同様になかなか知られていない部分もありますので、この地域社会に限らず、区の中で知られていないという行政事業、行政分野、こういったものについては、より広報、周知の工夫が必要であると再認識しています。","voiceIndex":39,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは要望で終わります。ぜひこれからも推進していっていただきたいと存じます。令和４年度の行政評価シートについてになるのですけれど、評価のところで、最終評価「Ｃ」の比率が、ざっくり見ても多いなと思っているのですけれど、「Ｃ」の比率、どのぐらいの割合なのか、分かれば教えていただきたいことと、また、それについてのご所見について伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"今後もこういった何か改善すべきところがないかということを、しっかりと見させていただきながら評価をつけていくということで、昨年度同様、今年度もやっていきたいと考えています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"「Ｃ」評価をつけられた後は、適宜、担当の所管課と連絡しながら、きちんとチェックをされているというようなイメージでよろしいのでしょうか。それとも、本当に最終段階になって、企画課がチェックするのか、「Ｃ」評価後のチェックの在り方、仕方を教えていただきたいのと、最終評価で「Ｄ」評価をつけられたら、それはもう完全に事業の廃止ということで、そうした見方でよろしいのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"「Ｄ」評価につきましては、もう単年度でやめるばかりのものが「Ｄ」評価ということではなくて、今後、廃止、それに向けた検討を行っていくというところも「Ｄ」評価に含まれますので、「Ｄ」評価についても、完了したもの、すぐ廃止するもの、あるいは。","voiceIndex":43,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"どうもありがとうあります。今のご答弁を伺いますと、結構最終段階で政策担当課がチェックをするのかなというようなイメージなのですけれども、それに誤りがあったら、私のイメージに違いがあったら、それは教えていただきたいのですけれども。所管評価が「Ａ」で、最終評価が「Ｃ」のものもあるのですけれども、そうした場合は、所管課との調整はどうやっているのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"少し個別具体的なところになるので、どういうふうに申し上げたらというところはあるのですけれども、所管が拡大の意向を持っていたとしても、その具体的な手法ですとか、効果というものがなかなか明るくならないと、これが区として「Ａ」というふうには判断できないのではないか。","voiceIndex":45,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、区民の方に、これがあまり知られていないということをご答弁されていたかと思うのですけれども、ぜひ区民向けの説明会など、もっともっと広報を強化していっていただきたいと思うのですけれども、この事務事業評価のシートの一部分を抜粋して、広報しながわに掲載して、このようなことをやっていますよとか、区民向けにもっと広報を強化していっていただきたいのですけれども、その辺り。","respondent":"吉岡政策推進担当課長","answer":"区民への見せ方やお示しの仕方については、時期、効果、そういったものもきちんと考えながら実施していきたいと考えています。","voiceIndex":47,"id":"exchange-022"}]},{"id":"topic-02","title":"人材育成に関すること","agenda":"人材育成に関すること","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"職員の人材育成についてお伺いします。職員提案制度についてなのですけれども、今年度も何件か職員提案ということでプレス発表に載っています。これは当然、我々議会のチェック機能としての１つだと思うのですけれども、この辺りについて、区長、副区長の前でプレゼンをされるというところ、現段階において、これが先ほど申し上げた区民のウェルビーイングに資する内容に今のところなっているのかどうか。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"例えば、ハードクレーム対応研修につきましては、これまでもクレーム対応研修は実施しておりましたが、今回こちらの研修は、判例を基に弁護士の先生に検証していただくということで中身を変えましたり、あとは。職員提案制度を経て実施した事業にかかわらず、こういった区民のウェルビーイングに資する事業かどうかというのは、冷静、客観的に判断していくものかなというふうに考えてあります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"例えば、品川区では、ノーネクタイというようなことが進んでいますけれども、あと名札を名字のみにするとか、そういった取組も進んでいる中で、若手の職員の中で、どういった感想が聞かれるのか、非常に働きやすいというふうになったということなのか、それとも、そういう声はあまり聞かれないのか。そういったことについて、何か情報を把握しているものがあれば、教えてください。","respondent":"田口人材育成担当課長","answer":"ただいまのご質問、研修についてですが、まず、私が先ほどご説明したハードクレーム対応研修と組織力・連携力向上研修はこれから実施するものでして、まだそちらについては感想などを把握しているところではありませんが、新人のお話が出ましたので。","voiceIndex":57,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"確認","question":"最後の部分の、いわゆる新規の職員の獲得、これは正式名称が今聞き取れなかった、書き取れなかったのですけれども、そういったプロジェクトは課長のところでやられているというところなのですか。その辺りもあとで聞かせてください。私は、新人だけではなくて、そこも大事だと思っているのですけれども、そういったところを確認させてください。","respondent":"田口人材育成担当課長","answer":"そのほかの実施した研修につきましてですが、それぞれ対象が異なっておりまして、まず、ロジックモデル作成研修ですが、こちらは基本的には係長級以上の職員を対象としまして、理論を学ぶという１日目の講義につきましては、全職員対象ということで実施をしております。","voiceIndex":59,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"提案","question":"ありがとうございました。職員提案制度については、職員が提案したものであろうとなかろうと、これについては、しっかりと評価をされていくという、先ほど、総務課長のご答弁もありました。我々も議会の中で様々な提案をさせていただいて、採用されるものもあれば、採用されないものも当然ある。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-026"},{"speaker":"山本委員","kind":"確認","question":"ご説明ありがとうございました。その中で、私から何点か質問をします。Mission、Vision、Valueが職員一人一人の方にどの程度浸透しているかということを確認しておりますでしょうか。そして３つ目が、研修で学んだことを実際の業務に生かせるように、ＯＪＴやメンタリングなど、どのようなその後の支援体制が整っているでしょうかということで教えていただければと思います。","respondent":"田口人材育成担当課長","answer":"ですが、毎年度３月に、こちらの人材育成基本方針の中で定めた成果指標などがありますので、そちらを職員アンケートという形で、どれぐらい浸透しているかなども含めて測定をする予定がありますので、１年に一度、そのような測定の機会を考えております。","voiceIndex":62,"id":"exchange-027"},{"speaker":"山本委員","kind":"提案","question":"Mission、Vision、Valueの浸透度合いは、やはり定期的にはかっていただくことで、より一層浸透が確認できた上で、より浸透を図られていくと思いますので、そのように進めていただきたいと思いました。研修前後の状況についてもアンケート等でご確認いただいているというところで、確認ができてよかったですし、翌年度以降、見直しに役立てていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-028"},{"speaker":"新妻委員","kind":"提案","question":"今年度は９件予算化されたということで、９件全部が分からなくて教えていただきたいのですが、既にカプセルトイや、３階ロビーの赤ちゃんシート、不妊治療のオンライン相談、子育て応援自販機、おむつ真空パック機の設置、ＥＶ車のシェアリングというものが設置されていて、９件のうち６点まで分かるのですが、あと３件、何が提案されているのかということを、もうこれ、実現。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"週に１回発行している庁内の広報の中でも、このMission、Vision、Valueの考え方について、毎週少しずつ説明をするということを行っております。品川区役所コールセンターということで、令和６年度につきまして、チャットポットですとか、コールセンター機能の導入を前提とした検討およびマニュアルの作成ということで実施をしています。以上が予算化した９件になります。","voiceIndex":65,"id":"exchange-029"},{"speaker":"新妻委員","kind":"提案","question":"それぞれありがとうございました。研修というのは非常に大事かと思っています。職員提案制度につきましては、ありがとうございました。新年度も、この９件は新年度の数ですよね。これも今後、公表されてくると思いますが、引き続き、職員の方からの職務に根差したといいますか、そういうお声もたくさんあるかと思いますので、これも継続してぜひ行っていただきたいと思います。","respondent":"田口人材育成担当課長","answer":"翌年度の研修につきましては、実施後のアンケートの結果を踏まえまして、また今後、練り直しをするところですが、基本的には、例えば、内容的には変わらないけれども、アプローチの仕方を変えるですとか、心理的安全性は講演会という形で実施しましたが、広くアプローチできる分。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"私からは、まず、職員研修についてお伺いいたします。それはどこなのか、委託したならば、その辺りを教えてください。","respondent":"田口人材育成担当課長","answer":"私からは、基本方針をどのように策定したかということについてお答えいたします。こちらについてですが、事業者への委託はしておりませんので、職員たちで作成いたしました。","voiceIndex":70,"id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"そうだったのですか。よろしくお願いします。続いて、職員提案制度についてお伺いいたしますけれど、対象者は全職員（管理者を除く）ということなのですけれど、様々斬新なアイデアが出てきたかなと考えています。それで、提案されている職員の方の年齢層、管理職を除くということなので、大体の想像はできるのですけれども、その年齢層と、あと男女の比率とかを、分かれば教えてください。","respondent":"勝亦総務課長","answer":"男女比につきましては、男性からのご提案が中心になっておりまして、ご提案いただいた方は、皆さん、男性職員からのご提案という形になってあります。","voiceIndex":72,"id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"分かりました。男性中心になっているというのは、もともと職員の比率とかもあるかと思うのですけれども、女性からのアイデアもぜひ積極的に取り入れていっていただきたいと思います。この職員提案制度、非常によい制度だなと考えていますので、引き続きぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-033"},{"speaker":"松永委員","kind":"提案","question":"私からは、職員提案制度についてです。では、このところの採用、不採用の通知方法は、どのようにされているのでしょうか。もう１つ、これも私、まだ、あまり制度のことに詳しくはないのですけれども、採用された方に対しては、何かインセンティブというか、賞状とか、何かそういったものはいただけるのでしょうか。その辺、２点についてお伺いします。","respondent":"勝亦総務課長","answer":"提案をいただいたものを採用するという達成感といいますか、モチベーション、そういったものが現状ではインセンティブになっているのかなというふうに考えております。","voiceIndex":75,"id":"exchange-034"},{"speaker":"松永委員","kind":"質問・要望","question":"もう１つが、やはり採用されたという喜びもあると思いますし、では、今後、ほかの方に対しても、例えば、商品券とかそういうものではなく、私がやったのだよというような、森澤区長からの賞状ではないけれども、認められましたという、採用されましたというような通知をもらえば、もっとモチベーションが上がるのではないかというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-035"},{"speaker":"のだて委員","kind":"提案","question":"それと、職員提案制度のところでは、今年度５件が採用されたということで、言える範囲で構わないのですけれども、どういった内容なのかというところを伺いたいと思います。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"トップとの対話ですが、こちらは新規採用職員と新任係長級で１０名ずつということで選抜をしておりますが、一度に話す人数としましては５名ずつに分かれまして、５名と区長という形で対話をしまして。今年度、５件採用、どういったものかですけれども、今まさにこちらの採用されたものを関係する所管のほうに、こういったものが採用されましたということでお知らせしまして、来年度の実施に向けて。","voiceIndex":78,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回新しくつくられた人材育成・確保基本方針、この中身を見ると、「憲法」ですとか「地方自治」という文言がないわけですけれども、品川区に入区する際、憲法を遵守するということで宣誓書を書いていると思うのですけれども、今もやられているかどうかも含めてお聞きしたいのですが、そもそも土台となっているのがそういった憲法や地方自治法ということだと思いますけれども。","respondent":"田口人材育成担当課長","answer":"今回の法を守るですとか、そのようなベーシックの部分が、この職員像というところに入っていないのはなぜかというところなのですけれども、ワークショップの中で、職員がいろいろ考えていく中で、そもそも公務員としては、そういうところは当たり前のことであって。","voiceIndex":81,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"技術職は、大体技術職にいるのかもしれませんけれども、様々、福祉関係の資格などもありますけれども、そうした方々が、特に希望される方が、しっかりこうした専門性を生かせる、そして、それを伸ばしていけるように、人材育成を強化していくということでやっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"田口人材育成担当課長","answer":"先ほどの質問で回答が漏れており、申し訳ございません。宣誓書につきましては、現在も入庁時に書いてもらっております。","voiceIndex":83,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"そもそも人が集まらないという問題もあると思うのです。その点を区はどう考えているかということも伺いたいのですけれども、実際、区として、これだけの新人の方に入ってきていただきたいという人数と、実際に採用した人数が分かれば伺いたいのですけれども、その後、質疑でもありましたけれども、様々な業務で、ハードルなどに当たって辞めていってしまうという方もいらっしゃると思うのです。","respondent":"田口人材育成担当課長","answer":"効果としましては、今後の採用に結びついていくというところはもちろんですが、こちらのＰＴに参加している職員が、改めて自身の仕事を見直すというところですとか、いろいろな職員、専門職なども２０名ちょっと集まって実施をしているものですので。","voiceIndex":85,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後、新人をどう増やしていくかというか、確保していくかというところで、いろいろ今やられているというところですけれども、やはり、先ほどありました働くことのやりがいというところで、ぜひそうしたところも訴えながら、そうした中に職員の給料の問題ですとか、人間関係を含め、あると思いますので、やはり初任給が民間に比べると公務員は低いというところがあると思うのですけれども。","respondent":"田口人材育成担当課長","answer":"先ほどの初任給という部分につきましては、人事委員会などで行っていることです。私の人材育成というところとは少し異なりますが、そのようなご意見ということで承って持ち帰りたいと考えています。","voiceIndex":87,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"説明をたくさんいただきまして、ありがとうあります。研修を通じて必要な能力を向上させていくということなのですけれども、職員のもともと持っている個性だったり、強みを伸ばすというか、そういったところはどういうふうにやっているかということをお聞きしたいです。例えば、診断ツールを使うなど、もしありましたら、教えてください。","respondent":"田口人材育成担当課長","answer":"ですが、研修の中で、例えば、採用４年目にやる研修などでは、それまで自分がどのような業務に携わってきたのかということを振り返りまして、またさらに、どういうところが得意だったのか、どういうところが苦手だったのか。","voiceIndex":89,"id":"exchange-041"},{"speaker":"せらく委員","kind":"提案","question":"管理職の皆様は、部署のチームのメンバーの皆さんに対しては、対応だったり、どういう言葉を投げかけてよいのかということは経験豊富だと思うのですけれども、そのメンバーからすると、やはりそういった上司がどういうふうにコミュニケーションをとったら、すごくスムーズにいくかというところが、もしかしたら知れるのではないかなというふうに思って、本日、提案というか、お話をさせていただきました。","respondent":"田口人材育成担当課長","answer":"こちらは、同じ種類のものではないのですけれども、先ほどご説明したカオナビ上でも似たような性格診断ツールなども用意がありまして、ただ、そちらを導入するかどうかにつきましては、実際の別の団体でやられたような実績などを踏まえまして。","voiceIndex":91,"id":"exchange-042"},{"speaker":"つる委員","kind":"提案","question":"いろいろな観点はそれぞれ議員が聞いていただいて理解させていただいたところです。先に、職員提案制度なのですが、もともと品川区は、２０１７年から職員提案制度があったのです。トップが代わられて新たなというところで職員提案制度をやってきたと思うのですけれども、これまでのものと、今やっているものの大きな違いはどういうところなのでしょうか。それを改めて教えてください。","respondent":"勝亦総務課長","answer":"従来の提案制度について、所管が若干違う部分がございまして詳細な部分はございませんけれども、現在やっている職員提案制度につきましては、区長、副区長、また関係する所管の部長等々の前でプレゼンを行い、そこで判断をしていくというような形は。","voiceIndex":93,"id":"exchange-043"},{"speaker":"つる委員","kind":"提案","question":"ここは、その上で、それぞれの提案してきている事業は、いろいろなレベルとかフェーズとかがあると思うのですけれども、「いや、そもそもそんな何億円とかという提案じゃないんだよね」と、「３桁ぐらいの単位なんだよね」とかという前提はあるのかというのは、これは多分、今の担当のところで答えていただければよいのですけれども、その金額のアッパーというか。","respondent":"勝亦総務課長","answer":"職員提案制度で提案いただく事業のレベル感といいますか、そういったものについては、具体的には設定をしておりませんで、ご提案いただいた事業の中でも、金額の小さいものから大きなものまで様々あります。具体的には、予算枠等は設定していないような状況です。","voiceIndex":95,"id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"人材なのですけれど、これもさんざんずっと言われてきて、私もいろいろな委員会のときに確認させていただいて、これは私自身も毎回言うからこそ自分で責任を取らなければいけないというところがあるわけですけれども、自ら処していかなければいけないところがあるわけですから、やはりどこまでいっても育てる側の意識というか、育てる側というか。","respondent":"田口人材育成担当課長","answer":"電話応対などの質を高めるというところにつきましては、もちろん研修というところも大事ではあるのですけれども、あとは心理的安全性という要素も大切になってくると考えておりまして、心理的安全性が高い職場ですと、例えば、電話応対などで、あまりよくない対応をした場合は。","voiceIndex":97,"id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"無表情で、こちらが挨拶をしていく、廊下で擦れ違うのだったらよいではないですか。だけど、それはすごく私は大切なことだと思っていますので、ぜひそういったところも、今、こういった計画もつくったりなんだりしている中で、大きく変わったなと、表情が変わったな、生き生きとしているな、もちろん職員のＥＳも上がったなというような形でぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"２点だけ、手短にお伺いさせてください。まとめて伺います。もう１点が、職員提案制度なのですけれども、これもご提案というか、お願いでありますが、制度の実現に際しまして、失敗を恐れない風土というか、失敗を生かす雰囲気というものをぜひお願いしたいと思っておりまして、お考えをお聞かせいただきたいと思います。","respondent":"田口人材育成担当課長、勝亦総務課長","answer":"こちらですが、クレームを対応するときには、そのときのケースによって同じ人がずっと対応したほうがよい場合ですとか、場合によっては、代わったほうがよい場合など、たくさんあるのですけれども、その中でも、例えば。そういった中で、各課において、こういった施策を進めていく中で、やはりしっかりウェルビーイングを獲得しながらも、失敗、あるものは、やはりトライ・アンド・エラーといいますか、軌道修正をしたり。","voiceIndex":100,"id":"exchange-047"},{"speaker":"西村委員","kind":"提案","question":"職員提案制度に関しましては、提案を出すということが職員の皆さんにとって魅力的であればあるほど、提案もどんどん上がってくると思いますので、提案した職員の方が何かしらの形で関われるような体制をぜひともご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-048"}]},{"id":"topic-03","title":"旧荏原第四中学校整備基本計画に係る検討状況","agenda":"旧荏原第四中学校整備基本計画に係る検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今後のスケジュールの中で、パブリックコメントに合わせて説明会を１２月頃やられるということですけれども、オープンハウス型ということで、学校跡地の活用ということですので、卒業生を含め住民の方にも知ってもらうためにも、教室型の説明会も、理解を深めるという意味でもぜひやっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"続きまして、ワークショップについてのお尋ねです。ワークショップにつきましては、公募型を１回開催させていただいて、高校生向けのものを１回、大学生向けのものを１回ということで、計３回実施する予定です。高校生向け、大学生向けについては、日程調整中です。","voiceIndex":109,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"説明会のところで、昨年同様オープンハウスということだったのですけれども、ぜひ、皆さんそれぞれの考えも発言の中で共有できたりしますし、そうした中で自分の認識も、こうしたほうがよいのではないかということが深まっていくと思うので、教室型の説明会、実施をしていただきたいと思うのですけれども、改めて伺います。","respondent":"吉岡政策推進担当課長","answer":"この施設を知っていただく、意見を聞かせていただくという機会のところで、ワークショップ、オープンハウス方式の説明会、また、年明けの３月には住民説明会ということで、いろいろな形の意見を聞かせていただく会、あるいは、こちらの考え方をお伝えする機会。","voiceIndex":111,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"経過の報告、ありがとうあります。当委員会でも何回か報告をいただいていて、そのたびにいろいろ要望とかを出させていただいているのですけれども、この前段の説明文の中にある庁内検討会を開催し、先進的な大型複合施設の事例を参考としたとあるのですけれども、この先進的な大型複合施設というのは、どこを指しているのか教えてください。","respondent":"吉岡政策推進担当課長","answer":"こちらも図書機能を中心としながら、市民の方の交流を促すというような大型複合施設でございまして、地域性は異なりますけれども、比較的、品川区が進めていくような施設の考え方と一致するようなところがあるのかなということで。","voiceIndex":113,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"昨年の都市問題会議で、私は、青森県八戸市に行って、まさに八戸市も、図書館というか、市として、本を活用した形で居場所づくりをやっていたのですけれども、その方向性としては時代に合っているのかなと思うのですけれども、ということは、以前にも委員会の中でも何回か言及はありましたけれども、近くに図書館が幾つかあるというのは、この資料の中にも分布している公共施設ということで。","respondent":"吉岡政策推進担当課長","answer":"委員からお話のございましたとおり、近隣の施設、図書館がありますので、そういった施設の在り方については、併せて考えていく必要があろうかというふうに認識しております。","voiceIndex":115,"id":"exchange-052"},{"speaker":"あくつ委員","kind":"意見","question":"近くの近隣施設の図書館は、私、個人的に利用させていただいているので、今後、在り方を検討していく中で、そういったものが統廃合されていくのは少し寂しいなという気持ちはありますけれども、そういったものも含めて、これから検討が進むのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-053"},{"speaker":"山本委員","kind":"質問","question":"ご説明ありがとうございました。私から、１点、質問させてください。検討の中に整備運営手法等の検討を進めているとあるのですけれども、そして検討会の開催内容の中にも、整備運営手法の比較検討とありますので、これはどのような工法を比較検討したのかということと、また、どのような意見や議論があったのかということをお教えください。","respondent":"吉岡政策推進担当課長","answer":"検討会では、どういった手法がよいかとか、そういった具体的な意見は出てきてはいないところではありますけれども、様々な情報を共有する中で、委員会内でしっかりとした整備内容を案として出していけたらなと考えているところです。","voiceIndex":118,"id":"exchange-054"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうございました。区民の皆様にとってよい施設となるように、そのような手法についても、いろいろと知っていただいた上でご検討いただきたいということと、検討委員会の方だけではなくて、区民の皆様に幅広くこの計画、検討状況を知っていただいて、常々申し上げていることなのですけれども、そして様々な声を集めていただいて、しっかりと検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"そういった中で、先日は、所管は違いますが、大原児童センターは、児童センターと、あとは児童発達支援センターを複合施設というか、違う機能、２つの機能を１つの事業者が指定管理の候補者として、文教委員会、厚生委員会にかけられて、そこでは可決したというふうに聞いておりますけれども、今回は、これは１つの事業者に、検討中ということなのかもしれませんが。","respondent":"吉岡政策推進担当課長","answer":"会社を設立していただいて、役割を区と同様に分散して持っていただくというようなやり方もありますので、そういった幅広い手法の検討を進めていきたいというふうに考えているところです。","voiceIndex":121,"id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。では、参考にお伺いしたいのですが、ご視察をされました広島県廿日市市の「まるくる大野」、ここについては、どういう形で運営をされていたのか、参考に教えてください。","respondent":"吉岡政策推進担当課長","answer":"こちらの「まるくる大野」については、ＰＦＩ事業でというところで、ＳＰＣに近い形でそういった様々な事業者を１つの事業者が束ねて運営をしているというような手法で運用しております。","voiceIndex":123,"id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"２点ほど確認します。そういうことで、今までされている野球、サッカー、サッカーはどうですかね。バレーボールはできるのでしょうか。それともう１点が、主な意見の中で、屋内で子どもが遊べるスペースというご要望が上がっております。この屋内で子どもが遊べる施設というのは、この屋内運動場とは別に検討がされているのかどうか、まずそこを確認させていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"庁内検討会の中で出てきた子どもが遊べるような屋内スペースですけれども、こちらは、出てきた意見でいうと、屋内運動場とはまた別のところで出てきた意見です。いわゆるプレイルームというような表現が正しいのでしょうか、そういったことで出てきた意見です。","voiceIndex":125,"id":"exchange-058"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。冷房が効いている中での祭りでした。体育館だったのでテントも張らなくて、そういう準備の負担も少し軽減されたというようなことがありまして、この全天候型の子どもが遊べる施設というか、そういうところがすごくこれから求められてくるのではないかなと思っています。そういう視点で、体育館、屋内運動場は１つある。","respondent":"吉岡政策推進担当課長","answer":"一方で、主な整備予定機能というところで、面積比較やゾーニングをやってありますので、こちらについては、面積の余剰があれば、こういったものもしつらえていきたいというようなご意見をいただいたところですので。","voiceIndex":127,"id":"exchange-059"},{"speaker":"つる委員","kind":"提案","question":"会派としても、いろいろ提案とかもあったかと思います。地域の方の声を一番重要で大事にしていただきたいという思いがあるところで、いよいよこうした、ご提示いただいたような想定スケジュールを示していただき、今後いろいろな質疑があるかと思います。品川区では、例えば、多世代交流施設とかいろいろな施設があるわけですけれども、新たな施設という、そういうカテゴリーになるということでしょうか。","respondent":"吉岡政策推進担当課長","answer":"この施設の検討の経緯からも含めましても、交流拠点という形になりますので、今までの多世代交流、いわゆる「ゆうゆう」とか、そういったものではなくて、新しい施設になるというふうに捉えているところです。","voiceIndex":129,"id":"exchange-060"},{"speaker":"つる委員","kind":"提案","question":"それこそこの行財政改革特別委員会でも、１０年ぐらい前、江東区のグランチャ東雲とかを視察させていただきました。先ほど、新妻委員からもあったように、屋内遊戯場とか、この十数年の中でもいろいろな意見とか提案があったと思います。委員会の資料などで確認すると、このエリアには、戸越公園や、それから文庫の森、エコルとごしがあって、回遊性をとあるのです。区の考えがあれば、教えてください。","respondent":"吉岡政策推進担当課長","answer":"一方で、たくさんのいろいろな方に来ていただきたいという思いから、しっかりとそういった駐車場の整備のところですとか、アクセス方法について、来やすい工夫、そういったものについては、しっかりと検討していきたいというふうに考えております。","voiceIndex":131,"id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"こうしたアクセスや設備についても、引き続き、地域の皆さんの声を第一としながらやっていただきたいと思います。その上で、そういう車両とかが、建物そのものにアプローチしやすい造りという、この辺りについては、駐車スペースもさることながら、動線といいますか、車両動線というのか、そこの辺りについては、どういう経緯なのか教えてください。","respondent":"吉岡政策推進担当課長","answer":"防災に関してというところも、やはり広場の部分を一定程度設けるですとか、あるいは体育館、あるいは、体育館以外のスペースについても、そういった災害時に転用できる、こういった考え方で整備に取り組んでいるというようなところです。","voiceIndex":133,"id":"exchange-062"},{"speaker":"つる委員","kind":"意見","question":"ＡＩオンデマンド、やはり先ほどの回遊と考えると、ここで回していくぐらいの感じでも、そういうものも考えられるのかなと思ったりするので、その先のあれですけれども、違うブランチでの話ですが、文庫の森があって図書館があるというのは、非常にきれいな流れかなということがありますし、その辺の関係者との連携なども考えられるのかなと思ったりもしますので、いろいろな形でここが生かされるように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"本当にこれが実現すると、インクルーシブ、サードプレイス、ネットワーキング、様々な機能を兼ね備えたすばらしい交流拠点となるかと思います。それは区民の公募で、どういうふうに募集していくのか。その辺り、現時点でどのように検討されているのかをお聞きしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"地域の方、品川区の区民の皆様に愛される名称というのは非常に重要だというふうに考えておりますけれども、こういった具体的なやり方については、これからまた検討していくような内容です。","voiceIndex":136,"id":"exchange-064"},{"speaker":"筒井委員","kind":"質問・要望","question":"はい、分かりました。ぜひ区民の皆様に覚えられやすい、愛されやすいようなお名前にしていっていただきたいと考えています。それであと、防災の点についてなのですけれども、活用方針の２６ページとかを見ると、ふだんは広場、屋外の広場を防災拠点として車が乗り入れたり、あと、図書館の位置が、これは避難所になるのですか。","respondent":"吉岡政策推進担当課長","answer":"図書機能に関しましては、本がどれぐらいの高さまで積むかというところもございまして、安全性に欠ける部分もありますので、そういったスペースはしっかりと見つけて、区民避難所として機能できるように、しっかりと検討していくです。","voiceIndex":138,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"この標準化、１８業務されていくということですけれども、これまで整理して、それぞれ変更になる部分はあるのかどうか伺いたいと思います。実際、システムを移行している中で、費用が結構かかっているのではないかと思うのですけれども、システム移行のための費用は、どの程度発生しているのか、現状で金額が出せるところがあれば、伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"どのような機能改修が発生したのかですが、管理項目の追加ですとか、データ連携仕様などのシステムの根幹となる箇所の改修ですとか、細かいところで申し上げますと、帳票の使用が５０種類ほど変更になったりですとか。","voiceIndex":144,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"全て国が負担するということになっているのかどうかというところも確認させていただきたいのですが、こうした移行を進めていく中で、やはり自治体がこれまで行ってきた制度が変更になる部分がご説明になかったので、あとでご答弁いただければと思うのですが、その変更にもしなって、不便になってしまうということでは困りますので、そうならないようにしていただきたいと思うのですけれども。","respondent":"横田デジタル推進課長","answer":"全額が国の負担かですが、現時点で、システム標準化事業で品川区に入る補助金の予定が、約２５億円になりまして、１００％には大きく満たないという状況になります。","voiceIndex":146,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"そうした中で、実際に今、いろいろこの標準化を進めていく理由をご説明いただきましたけれども、６０秒で手続ができるようになるとかということで、実際、自治体の手続でそういったことはないわけですけれども、その現実と、６０秒で完了するということはかけ離れているなというふうに思うのですけれども、実際、６０秒で手続完了するようになるのかどうか伺いたいと思います。","respondent":"横田デジタル推進課長","answer":"２番目のデジタルデバイドについてなのですが、高齢者地域支援課の範疇になってしまうのですが、近年、スマホ教室などの実施によりまして、誰一人取り残されないという側面から支援を行う一方で、全ての方がデジタルの恩恵を享受するという考え方が広がりつつあります。","voiceIndex":148,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたいろいろ目指していくということなのですが、これまでの区民が利用してきた区の制度が変更されて利便性が悪くならないようにしていただきたいと思いますし、本来、私たち、このガバメントクラウドをやめるべきだと言ってきましたけれども、実際問題、今後幾らかかるか分かりませんけれども、推定６０億円ぐらいかかるという中で。","respondent":"横田デジタル推進課長","answer":"システム標準化につきましては、システム標準化法に基づいて進めておりますので、法令にのっとりまして着実に進めてまいりたいと考えております。","voiceIndex":150,"id":"exchange-069"},{"speaker":"筒井委員","kind":"質問","question":"今お話にあったとおり、費用が３２億円さらに上乗せされる予定だという一方で、国の補助金は２５億円ということなのですけれども、その差額は区の持ち出しなのか。ほかの特別区も同じような状況なのか、また、国の補助金２５億円というのは、さらに追加して国からもらえるということはないのでしょうか。その３点、お伺いいたしたいと思います。","respondent":"横田デジタル推進課長","answer":"補助金の追加が出るのかですが、現時点では、追加の補助金はない予定ですが、今、東京都とほかの自治体と組んで、国にさらなる補助金を要求しています。","voiceIndex":152,"id":"exchange-070"},{"speaker":"筒井委員","kind":"質問・要望","question":"どうもありがとうございました。ぜひ国に対して要求をしていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6835#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":60507,"voices":159}},{"id":"r06-20240927-19","meetingId":"r06-cm09","date":"2024年9月27日","dateIso":"2024-09-27","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"エコルフェス－２０２４ ＡＵＴＵＭＮ－の開催","agenda":"エコルフェス－２０２４ ＡＵＴＵＭＮ－の開催","exchanges":[{"speaker":"まつざわ委員","kind":"意見","question":"１点だけ、ＳＤＧｓ部、青稜の中高の方がやられていますが、これは、公立というか、品川区がＳＤＧｓを推進していく中で、私立学校でもいいのですが、せっかく区立で近くにも中学、例えば都立だと大崎高校とかいろいろある中で、これは何で、何かいつも青稜かなという勝手なイメージがあるのですが、そこら辺の何か説明があれば。","respondent":"中西環境課長","answer":"エコルとごし、それから環境課としましても、様々な学校とつながれればと思ってあります。例えばエコルとごしの学生ボランティアでも、学生さんとうまく連携できたらと思ってありますので、引き続きそういった枠の拡大というものは考えてまいりたいと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"４月に行われたエコルフェスにも参加させていただいて、すごくにぎやかで楽しいイベントだったと思うのですが、その中には、何階だったか忘れてしまったのですが、小さな子どもたちが遊ぶようなコーナーが設けられていて、たしかそこもボランティアの生徒さんが、何というか、面倒を見るという言い方はあれかもしれませんね、子どもたちの相手をしているという場があって、すごく人気があったのですが。","respondent":"中西環境課長","answer":"今回も、「無垢の積み木で遊ぼう！」というコーナーで同様に、たしか多目的室だったと思うのですが、紙製人工芝を敷設させてただいて、木材に触れるというブースは設ける予定です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"吉田委員","kind":"意見","question":"課長から言っていただいたその場が紙製の人工芝だったので、なかなかそれを外で用いるとなると、何か摩滅は早いし更新も頻繁で、まだ高価だしという課題はあると思うのですが、やはり品川区の環境の課題としては、人工芝のプラスチックというのは気にしておられるのだなということが分かったので、すごくうれしかったのですが、引き続き。","respondent":"中西環境課長","answer":"太陽光ですぐに摩耗してしまったり、色が劣化してしまうというところもあります。私どもとしても非常にいい素材であると思ってありますので、今後も展開については検討してまいりたいと思ってあります。","voiceIndex":10,"id":"exchange-003"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"まつざわ委員","kind":"質問・要望","question":"情報を捉える方法として、例えば今は普通のニュースであったりの部分でしか情報が捉えられないと思うのですけれども、区としてこの情報というのを、例えば風水害に対し、また地震というのも、風水害が来ますという情報の中で、区がどういうふうに情報を発信しているのかというのを教えていただきたいのが１点と、在宅避難推進の中の声かけ、共助、平時からの顔が見える関係の構築。","respondent":"羽鳥防災体制整備担当課長、平原防災課長","answer":"台風につきましては、３日ほど前から区の中でも体制を取りまして方針を決定し、状況によっては自主避難施設の開設などを検討した上で、早めに情報を出すように心がけているところです。一朝一夕に何かすばらしい解決策があるというところには行けてはいないですけれども、なかなか個人情報の部分と災害時の対応のバランスをどう取れるかというところは、私どもも一緒になって考えさせていただいているところです。","voiceIndex":16,"id":"exchange-004"},{"speaker":"まつざわ委員","kind":"確認","question":"そうなのですよね。これは私も一緒に探していきたい部分です。防災訓練の話が出ました。そこら辺の、新しいことを始めたことで、何というのですか、感覚を教えてほしいのと、あと、公助の支援体制の整備で、情報拠点の中で安否確認というのはいろいろやりますけれども、私の地域だと多分避難所訓練の中でも、情報の確認というのですかね、伝達の訓練で本格的なのはまだやったことはないのですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"その部分は、もっと町会と密に連携していただきたいと。最後に確認したいのですが、７の情報発信に令和７年度より「災害ポータルサイト・アプリを新規導入」と書いてありますが、これというのが、５の在宅避難者の把握、要は状況を把握するという、スマホアプリとかデジタル技術を活用した把握方法を検討と書いてありますが、これがイコールなのか、また全く違うものなのか、それだけ最後に教えてください。","respondent":"平原防災課長","answer":"結論から申し上げますと、ものとしては別ですが、ただし別々で運用するのではなくて、別のシステムをこのポータルサイト・アプリに連動させていくような形で、運用としては一本の運用でできるように、今現在検討しています。","voiceIndex":22,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、今の品川区のスマホの防災アプリがありますね。ああいうやつですか。ああいうものがあって、それにこうやって新しいものが入ってくると。","respondent":"平原防災課長","answer":"少し細かいお話になりますけれども、現在検討しているのは、区の災害対策本部での情報共有のシステムが今もう既に存在しているのですが、それを大きく改善させていただいて、そこにいろいろな情報が集約できるようなもので今考えてあります。","voiceIndex":24,"id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ここで注意しなければいけないのが発信の方法で、いろいろな方がいらっしゃって、高齢の方も結構こういう防災アプリというのは取得率が高いと聞いていて、ただ、障害がある方だったり多言語が必要だったりというところがあると思うので、もちろんいろいろと考えてくださっているとは思うのですが、ぜひそういうところも注視しながら進めていただきたいなと思うのですが。","respondent":"平原防災課長","answer":"現状は、現在、ポータルアプリといいましょうか、先ほど言いましたとおり、災害対策本部の情報共有システムの構築を進めているところでございまして、そこから派生した形でこのアプリが出てくる形になりますので、このアプリを中心に。","voiceIndex":27,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ご高齢の方々も分かりやすいデザインがいいというお声だったり、障害にも適用されているようなものがいいだったり、多言語化がというご要望もいただいていますので、ぜひ、重要だとおっしゃっていただきましたので、引き続き取り組んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"この辺のことをどのように各避難所運営会議とかの運営に携わる方々に理解いただき、またいろいろな実際の災害が起こったときにきちんと機能してもらえるかというようなことでの支援というか、もしかしたら訓練とか、そういう話かもしれないですが、そういうところを今現在どう進めているのかと、今後、まだまだこれからなのかなというところも感じているので。","respondent":"平原防災課長","answer":"そういったところで、極力負担が入らない形でそういうところを統括していただくことを現在お願いしていますが、在宅避難の部分に関しては、極力何か負担が増えるということがないように、公助の支援という形を充実させていければと、今検討を進めさせていただいているところです。","voiceIndex":31,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"建前としてのお話は承っているということは承知しているみたいですが、では現実問題どうするか。そこで、やはりそういう公助というところがどこまでできるか。人的なリソースもすごく必要かなと思っているのですが、そういうことも含めて、やはり重々支援をしていっていただきたいなとも思いますが、改めてご答弁をお願いします。","respondent":"平原防災課長","answer":"１つ目には、平素からという形で、体制をしっかり考えて準備しておくという意味での支援、そこは私どものまさに仕事の中心だと思ってありますのでしっかりやらせていただくのと同時に、災害が発生したときの、委員にまさにご指摘いただきました人的リソースという意味では。","voiceIndex":33,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"ボランティアということで、本当にそれが大きな力を発揮できれば、何というのか、頼もしい存在になってもらえれば、それにこしたことはないと思いますので、ぜひそういうことでの支援の体制というのは進めていただきたいと思います。どれぐらい今、設置が進んでいるのかというのが、ある程度分かれば教えていただきたいのですが、今の配布の状況というのはどんな感じでしょうか。","respondent":"平原防災課長","answer":"エレベーター用防災チェアですけれども、現在、まだお話をいただいて最終的に詰めている段階で、具体的な数としてはまだ発生してございませんが、引き合いといいましょうか、お声は結構多数いただいているところです。","voiceIndex":35,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"かなり危険性を考えなければいけないので、本当に住民にそこまでのことを区として後押ししていくのはどうなのかというのはあるのですが、例えばマンション防災アドバイザーの派遣というのを今やっていますけれども、こういったものの中のメニューというか、求められているマンションがあれば、もしものときは、本当にもう緊急事態であれば自分たちで救出できるということであれば。","respondent":"平原防災課長","answer":"その次の段階として、閉じ込めだったけれども少しぐらい待てるよとか、そのためにエレベーターの防災チェアで何とか数時間はいけますという形であれば、そういうことで落ち着いていただくようなところ、現実にこれがどういうものなのかを知っていただくというところ。","voiceIndex":37,"id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。いずれにしてもエレベーターの閉じ込めというのは、こういう都心のマンションがたくさんある地域では大事な防災対策の一つということで区も認識していただいて、特にエレベーターのことについてのいろいろな対策も考えていらっしゃるということは分かりましたので、今後ともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-014"},{"speaker":"えのした委員","kind":"質問","question":"そうすると、お困り事の中で通報訓練、消火訓練、避難訓練、地震体験車、煙体験、ＡＥＤなどがありますけれども、こういうのをやりたいときは、そのマンションの方は多分お話を聞くだけでしたら、近くの地域センターとかマンションのどこか、１階のホールなどでもできるかとは思うのですが、こういった実際の訓練をやってみたいなというときには、例えば区のほうでマンションだけの防災訓練というか。","respondent":"平原防災課長","answer":"まず場所については、基本的には多数の参加を得るという意味で、やはりマンションでやると、そのままの下で何かをやっている、見てみようみたいな形になるのとか、負担が少ないという意味もあって、例えばマンションの会議室、集会室、あるいはマンションの前のエントランス。","voiceIndex":41,"id":"exchange-015"},{"speaker":"えのした委員","kind":"質問","question":"本当に防災体験館などを活用していただければいいなとは思っているのですが、まだこれからの取組なので、応募というのは来ているか、状況は分かりませんが、もしそういうお声があれば、どのぐらいご連絡が来ているかというのをお知らせ願えますでしょうか。","respondent":"平原防災課長","answer":"ただ、その中でも、例年ご相談いただく、あるいはご講演いただく、あるいは訓練まで行くというのが１０件以上の単位でやらせていただいておりますので、年中どこかでやらせていただいている状況はつながっておりますし、あるいは、しながわ防災学校でも現在ご案内していますが。","voiceIndex":43,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"在宅避難者に対しての物資、各避難所に物資を取りに来るということで書かれているのですが、基本的に在宅避難の場合は、７日分は家庭内備蓄をしてくださいよということで推奨されているということなのですが、それでも、各避難所にそれができていない方はもらいに行くと受け取れるということで考えていいのか、そして、ここの１ページのところにも。","respondent":"羽鳥防災体制整備担当課長","answer":"物資についてのご質問ですので、私から回答します。在宅避難されている方は７日分の家庭内備蓄を推奨していますけれども、なかなか備蓄ができていない方が避難所に取りに来られた場合ですけれども、もちろん物資をお渡しする想定です。","voiceIndex":47,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"それ以外に在宅の避難者が考えられるのかなと思うのですが、その８万７,０００人という本来であれば避難所に来る人が、在宅避難という考え方なのでしょうか。でも、８万７,０００人は避難所に来て、それ以外の方で在宅避難ということになるのではないかなと思うのですが、その在宅避難の方の分というのはどれぐらいの備蓄ということで想定されているのかを伺いたいなと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"ですので、まずは、そういうことも含めて７日間、家庭で備蓄をしてくださいということを呼びかけているところです。７日間を過ぎますと、国などから支援物資がプル型で届いてまいりますし、４日目以降であればプッシュ型でも支援物資というのは届いてまいります。","voiceIndex":49,"id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"これは新しく品川区としても作られたものということになると思うのですが、そういうところに、区によっては在宅避難のガイドブックというのを作っているところもあったのですが、例えば在宅避難のためにこういうことをしてくださいよと、例えばこんなものもきちんと備蓄してくださいよみたいな、そういうことも多分載せられているのかなと思うのですが、その点も伺いたいのと、それから。","respondent":"平原防災課長","answer":"こちらのハンドブックにつきましては、後ほどの報告の中の携帯トイレの配布事業の中で触れしますが、すみません、本日ではないのですが、準備ができましたら、区議会の皆様にもぜひご覧いただくような形を取らせていただければと、現在検討させていただいているところです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２ページのところの、避難行動要支援者のところですが、避難所に物資を取りに来られない方は、個別避難計画に記載された支援者や地域の共助による配布などで、輸送支援を検討するということで書かれているのですが、今、個別計画を立てられた人数と、そのうち在宅避難者の人数というのが、高齢者と障害者、それぞれ立てられていると思うのですが。","respondent":"平原防災課長","answer":"避難行動要支援者の個別避難計画における人数については、大変申し訳ございません、所管が福祉部で行っている関係で、最新のものはお持ちしておりませんけれども、前回委員会でご報告させていただきましたとおり、高齢者を対象としたものにつきましては。","voiceIndex":53,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"障害の方とかが、基本的に在宅避難ということで避難所には行かない計画になっているというのは、具体的に伺っているのですが、そうではなくて、必ずそういうふうに、そうはいっても火事になったり、かなり巨大でどうしても住めなくなるというときに、どうしたらいいのだろうという声をいただいているのですが、基本的に避難所に避難する計画になっているというのが、防災課の捉え方なのか。","respondent":"平原防災課長、滝澤災害対策担当部長","answer":"在宅避難のところですけれども、現在、建物の状況を確認しながら進めていると聞いてございまして、およそ在宅避難の可能性が高いというお話を聞いてありますが、個別避難計画はあくまで避難の対象とするものですので。これは、例えば総合体育館であるとかきゅりあんであるとか大きなところ、品川区でも今４か所ぐらい考えていますけれども、大きな許容力のあるところをある意味一次福祉避難所として、この地域の人はここに行ってください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"それと、やはり障害の方々も、それぞれ障害の種別によって不安の中身が違いますので、その計画を立てるに当たっても障害者の方々のご意見を伺っていただいて、できればそこの計画を検討するところにも入っていただくとかも含めて、そういう声を聞いていただいて、それを反映していただくということでお願いできたらなと思うのですが、その点を伺いたいと思います。","respondent":"平原防災課長","answer":"避難行動要支援者の具体的なお話につきましては福祉部所管ですので、今の委員のご意見につきましては福祉部にお伝えさせていただければと思います。避難行動要支援者の全体計画につきましては、今年度中に改訂いたします。もう大詰めに進んでおります。","voiceIndex":59,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"障害者の、当事者の声もぜひ聞いていただきたいなと思うのですが、その点はいかがですか。","respondent":"平原防災課長","answer":"今お話ししましたとおり、計画そのものという形ではもうほぼ作業が終了しておりますので、今後、実際にそこを運用していく中で、いろいろなお声を聞ければと考えていますので、そういうところはしっかりやらせていただければと思ってあります。","voiceIndex":61,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多分その計画も、何というのですかね、見直して、またよりいいものにというところにもなっていくかと思いますので、そういうところどころでぜひ当事者の声も入れていただきたいということで、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。在宅避難に関連してですが、発災が起きて、風水害も地震もそうだと思うのですが、防災行政無線のことでお尋ねさせていただきたいと思います。確認をさせていただきたいのが、親があって子局がありますよね。子局が今４０４あって、屋外の子局が１５５局だと思うのですけれども、それでよろしいのか、確認をさせてください。","respondent":"羽鳥防災体制整備担当課長","answer":"防災行政無線の件につきましてなので、私から回答します。数に関しては委員のおっしゃるとおりです。","voiceIndex":65,"id":"exchange-025"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。これは、１人で暮らしている方で、高齢者も特にそうだと思うのですけれども、これだけ屋外の子局があって、地域によって聞こえる、聞こえないというのが結構私の地域でもお声があります。地域の声、区内全体から見て、そういういろいろなお声があると思うのですけれども、その辺についてどういう声があるのか、お聞かせいただきたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"お電話していただいて、どういう放送が流れたかということを確認していただけるようなダイヤルも設置しています。そういう聞こえづらいというお声がありますので、様々な形で対応しています。","voiceIndex":67,"id":"exchange-026"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。それについて何か改善というのはすごい難しいと思うけれども、もうそれだけを頼りにしている方も多分いらっしゃると思うので、改善はいろいろやっているかと思うのですが、いま一度この防災無線については、アナウンスの仕方を含めて、今後も含めてやっていただきたいと思いますので、これは要望としてよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"在宅避難の必要性という、いわゆる推奨していくということは大事なことだと思うのですが、この在宅避難で、ここにも書かれているように備蓄、いわゆる食料だったり水だったりトイレだったりというのは上がってくるのですが、医療品、医薬品、こうした面についてはどういうふうにお考えでしょうかというところが１点気になっているところです。","respondent":"平原防災課長","answer":"委員ご指摘のとおり、個々人に応じて必要なものは変わってくるかなと思いますので、そういうところは、今後、後ほどご説明しますが、携帯トイレの配布事業で併せて同封します新しい防災ハンドブックにも記させていただきましたけれども。","voiceIndex":70,"id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"それは電話なのか、それとも行って相談するのかにしても、生活そのものの中で困っていることの相談ができる体制を、避難所ではつくっておくのが必要なのではないですかというところでお話をさせていただいているので、その辺の、先ほど塚本委員も質問をした中で、一つ、避難所の体制として関わることが増えていくのではないですかということもそうですが、だからこそ、きちんと避難所に保健師を置くなり。","respondent":"平原防災課長","answer":"この中には、医師会の協力をいただきまして、医師、災害時の薬事コーディネーター、それから、看護師等々の医療スタッフが配置されますので、そういった医療体制はそちらで充実するということと、これは別に避難所の医療機関ではございませんので。","voiceIndex":72,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"ですので、医療に限った話を今しましたけれども、そうではない、生活をしている中で、いろいろなところで、備蓄品をもらいに行く、それはもう普通にありますよ、できますよということですけれども、そうした医療など生活にまつわることの相談というところをきちんと対応してくださる体制を、どうかお願いしたいと思いますが、いま一度ご答弁をいただけますでしょうか。","respondent":"平原防災課長","answer":"自宅が無事で在宅避難ができる体制のときということで、避難所避難のところでご説明させていただきましたが、避難所避難は家が壊れて初めて行く権利があるというものではなくて、不安な方も行っていただくことで十分ですので。","voiceIndex":74,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたところの健康状況というのでしょうか、そういうものも把握できるような形で取れるといいだろうなと思うのですが、例えば高齢者の方で避難所よりも自宅のほうがいい、少し不安だけれどもやはり自宅のほうがいいといってとどまっている方だとか、こうしたことでデジタルを通じて在宅の方を把握するためのことに、ご自分で私はここにいますよということをきちんと登録できたり。","respondent":"平原防災課長","answer":"ただ一方で、もともと要配慮の方については、先ほどありましたとおり支援者というものが前提となっているところもありますので、そういう方々を介してどうするか、あるいはそういう方々がいない方に対してはどうしていくのかというところは。","voiceIndex":76,"id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"いろいろとありがとうございました。在宅避難を推奨していくからには、その在宅の方々の支援策の体制をきちんと取っておくことが大事だというところで、質問をさせていただきました。今検討中のこともありますけれども、できるだけ在宅避難が可能な体制は、個々に備蓄なり取っていただきますが、そこを可能とするような公助の体制の整備を、これからもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"医療から福祉。これは各避難所に課長が１人ずついないと、対応できないのではないかなと。今、そこまでやっているのですかと。それから、缶詰などはもう１０年、２０年も大丈夫ですよというようなことも書かれて、やはりそういう衛生管理、煮沸して熱で長くもつようになっているということで、これは自分も実験して、今のところ体調が大丈夫ですから、大丈夫だと考えています。これは少し余談ですが。","respondent":"溝口防災まちづくり部長、平原防災課長","answer":"ただ、道全てというところなのですが、区内全域で３２８キロメートルぐらい、たしか区が管理している道路全部ありますので、多分全ての道路をやらないと、皆さん。物資については、避難行動要支援者を中心に取りに来られない方々に対してどのような形で地域の体制をつくれるかについては、地域の方々にかなり大きなご協力を得ていかなければ立ち行かないとは思うのですが、ただ、それだけではなくて。","voiceIndex":80,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"在宅避難の方が様々なそういう諸問題が起きるということで、だけど、本当にきめ細かく様々なことを考えられて対応されて、頑張られていると思います。ですが、やはりこれが基本で、どうしても家から離れられない人もいらっしゃるし、そういう意味で、あと避難場所の分散を考えたらやはりこれがベターだと思いますし、ぜひ今後も普及啓発に私は頑張って推進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-034"},{"speaker":"ゆきた副委員長","kind":"確認","question":"様々なご答弁をありがとうあります。聞きながら、自助の取組の啓発、あとマンション居住者と地域住民との間の共助の啓発について、区として進められているのを確認させていただきました。炎天下の中でクーラー、扇風機などが使えない状況だと、命に関わるところになってきます。","respondent":"平原防災課長","answer":"災害対策を進める上では、電気以外にも、先ほど須貝委員からもご指摘がございましたとおり、様々な部門と連携していかなければならないことも多うありますので、当然そういうところにつきましても、環境課と連携させていただきながら進めさせていただければと考えています。","voiceIndex":86,"id":"exchange-035"},{"speaker":"ゆきた副委員長","kind":"確認","question":"ぜひ所管を超えて、連携をさらに強めていただければと思います。先ほど、防災ハンドブックのところで一部紹介されているというお話もあったのですが、私も確認させていただきまして、マンション防災ハンドブックには、「停電・断水に備える」と書かれ、「クーラーが使えないことを想定し、夏場は冷却シートを準備する」とは記載されています。","respondent":"平原防災課長","answer":"現在、災害対策につきまして、東京都をはじめとして様々なところで様々な取組がなされておりますので、そういうところが例えば防災区民組織、あるいは東京都の部局によっては町会・自治会という形で客体が異なっておりますけれども。","voiceIndex":88,"id":"exchange-036"}]},{"id":"topic-03","title":"携帯トイレ全区民配布","agenda":"携帯トイレ全区民配布","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"赤ちゃんの分も配布があるのですかというご質問いただいているので、その点はどうなっているのか、まず確認します。単身者だけを回って、また同じ地域に２人世帯の方、３人世帯の方というふうに配るということをご説明されたと思うのですが、効率的にこれはどうなのかなというのがあったので、なぜ単身世帯からとしたのか、その辺のところをお聞きしたいと思います。お願いします。","respondent":"平原防災課長","answer":"続きまして、コールセンターですが、稼働時間は平日の１０時から１７時の間ということになりますが、それ以外の時間帯はＡＩのオペレーターが対応するということと、あと、メールでの対応も受け付けてありますので、そういうところのご案内もする予定です。","voiceIndex":94,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"年齢制限はないということは確認いたしました。それで、３人の体制をしてくださるということですが、想定されることとして、コールセンターで、トイレの配布のこと以外にも多分いろいろなことを聞かれると思われるのですが、そうしたことへの対応も加味しての体制を取られているのかを確認させていただきたいと思います。","respondent":"平原防災課長","answer":"しっかり私どもで対応させていただければと考えています。","voiceIndex":96,"id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"確かにコールセンターの方が全てお答えするというのは不可能だろうとは思いますので、できるだけ防災に関連するところは、わざわざその所管へのご連絡ではなく、そこで対応できればいいかなとは思いますけれども、でも、質問内容が多岐にわたってそれが掘り下げられた質問になってくると、答えられないという状況もあると思いますので、そこは柔軟に対応をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6837#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":41176,"voices":106}}]);
